import json

class JsonParser:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_function):
        self.registry[id] = factory_function

    def create_from_json(self, json_string):
        data = json.loads(json_string)
        if 'id' in data and data['id'] in self.registry:
            obj = self.registry[data['id']]()
            for key, value in data.items():
                setattr(obj, key, value)
            return obj
        else:
