import hashlib
import os
from tqdm import tqdm
import concurrent.futures
import logging
import base64

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def read_file_in_chunks(file_path: str, chunk_size: int = 8192):
    """"""Reads a file in chunks and yields each chunk.""""""
    try:
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                yield data
    except FileNotFoundError:
        logging.error(f""File not found: {file_path}"")
        raise
    except Exception as e:
        logging.error(f""Error reading file {file_path}: {e}"")
        raise

def compute_hash(file_path: str, hash_algorithm: str = 'md5', chunk_size: int = 8192) -> str:
    """"""Compute the hash of a single file.""""""
    try:
        hash_func = hashlib.new(hash_algorithm)
    except ValueError:
        logging.error(f""Unsupported hash algorithm: {hash_algorithm}"")
        raise

    try:
        total_size = os.path.getsize(file_path)
        with tqdm(total=total_size, unit='B', unit_scale=True, desc=f""Hashing {file_path}"") as pbar:
            for chunk in read_file_in_chunks(file_path, chunk_size):
                hash_func.update(chunk)
                pbar.update(len(chunk))
        return base64.b64encode(hash_func.digest()).decode('utf-8')
    except Exception as e:
        logging.error(f""Error hashing file {file_path}: {e}"")
        raise

def hash_multiple_files(file_paths: list, hash_algorithm: str = 'md5', chunk_size: int = 8192) -> dict:
    """"""Hash multiple files using specified algorithm and chunk size.""""""
    results = {}
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_file = {executor.submit(compute_hash, file_path, hash_algorithm, chunk_size): file_path for file_path in file_paths}

        for future in concurrent.futures.as_completed(future_to_file):
            file_path = future_to_file[future]
            try:
                results[file_path] = future.result()
            except Exception as e:
                logging.error(f""Error processing file {file_path}: {e}"")

    return results

def compare_hashes(hash1: str, hash2: str) -> bool:
    """"""Compare two Base64 encoded hashes.""""""
    return hash1 == hash2
