def find_smallest_missing_exceeding_threshold(numbers, threshold):
    numbers_set = set(numbers)
    candidate = 0

    while True:
        if all((candidate + num) > threshold for num in numbers_set):
            if candidate not in numbers_set:
                return candidate
        candidate += 1

        # Optimization: If we reach a point where adding the maximum number plus threshold
        # is still less than candidate, break early.
        max_num = max(numbers, default=0)
        if (max_num + threshold) < candidate:
            break

    return -1
