def generateUserHash(json_string):
    if not checkJSON(json_string):
        print(""Error: JSON validation failed."")
        return """"

    try:
        data = json.loads(json_string)
        name = data[""name""]
        sha256_hash = hashlib.sha256(name.encode()).hexdigest()
        return sha256_hash
    except Exception as e:
        print(f""Unexpected error during hashing: {e}"")
        return """"

