0,Create a Python script that accepts a list of singular strings and calculates the count of unique anagram pairs within that list. Employ a Trie data structure in crafting a function to effectively recognize and tally these anagram pairs. The function must also provide the total number of milliseconds consumed to determine the count of distinct anagram pairs. It's given that the input list will not have any repetitive strings.,['CWE-330'],,"['```python
import time

class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in sorted(word):
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.count += 1

def count_unique_anagram_pairs(words):
    start_time = time.time()

    trie = Trie()
    pair_count = 0

    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in trie.root.children:
            pair_count += trie.root.children[sorted_word].count
            trie.insert(sorted_word)
        else:
            trie.insert(sorted_word)

    end_time = time.time()
    elapsed_time_ms = (end_time - start_time) * 1000

    return pair_count, int(elapsed_time_ms)

# Example usage:
words = [""listen"", ""silent"", ""enlist"", ""google"", ""gogole""]
pair_count, elapsed_time_ms = count_unique_anagram_pairs(words)
print(f""Unique anagram pairs: {pair_count}, Time taken: {elapsed_time_ms} ms"")
