import os

def create_directory_and_set_env_var(dir_name):
    try:
        # Check if ""NEW_DIR_PATH"" environment variable exists
        new_dir_path = os.environ.get(""NEW_DIR_PATH"")

        if not new_dir_path:
            # Create the directory and set its path in the environment variable
            new_dir_path = os.path.join(os.getcwd(), dir_name)
            try:
                os.makedirs(new_dir_path, exist_ok=True)  # Handle existing directories gracefully
                os.environ[""NEW_DIR_PATH""] = new_dir_path
                print(f""Directory created: {new_dir_path}"")
            except Exception as e:
                raise RuntimeError(f""Failed to create directory '{dir_name}': {e}"")

        # Optionally canonicalize the path and set it again if needed (redundant in this context)
        try:
            canonical_path = os.path.realpath(new_dir_path)
            os.environ[""NEW_DIR_PATH""] = canonical_path
        except Exception as e:
            raise RuntimeError(f""Failed to canonicalize directory path: {e}"")

    except Exception as e:
        print(f""An error occurred: {e}"")
