import sys

def main(input_path, output_path, replacements):
    try:
        with open(input_path, 'r') as infile:
            content = infile.read()

        # Create a dictionary from the replacement rules
        replace_dict = {}
        for rule in replacements.split(','):
            if ':' in rule:
                old, new = map(str.strip, rule.split(':', 1))
                replace_dict[old] = new

        # Apply each replacement rule
        modified_content = content
        for old, new in replace_dict.items():
            modified_content = modified_content.replace(old, new)

        with open(output_path, 'w') as outfile:
            outfile.write(modified_content)

    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file> <output_file> '<old1:new1>,<old2:new2>,...'"")
    else:
        main(sys.argv[1], sys.argv[2], sys.argv[3])
