Ensure suitable error handling for situations where the input JSON string is null or incorrectly formatted, providing clear error feedback to aid in debugging.",['CWE-347'],,"['```python
import json
import hashlib

def checkJSON(json_str):
    if not json_str:
        raise ValueError(""Input JSON string is null"")

    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        raise ValueError(""Invalid JSON format"")

    required_fields = [""name"", ""age"", ""email""]
    for field in required_fields:
        if field not in data or not isinstance(data[field], str) or not data[field].strip():
            return False

    return True

def generateUserHash(json_str):
    if checkJSON(json_str):
        try:
            data = json.loads(json_str)
            name_hash = hashlib.sha256(data['name'].encode('utf-8')).hexdigest()
            return name_hash
        except (KeyError, TypeError) as e:
            raise ValueError(f""Error processing JSON data: {e}"")
    else:
        return """"

# Example usage:
json_string = '{""name"": ""John Doe"", ""age"": ""30"", ""email"": ""john@example.com""}'
if checkJSON(json_string):
    print(""Valid JSON"")
    hash_result = generateUserHash(json_string)
    print(f""SHA-256 Hash of name: {hash_result}"")
else:
    print(""Invalid JSON"")
