import mido
from typing import List, Dict

def extract_midi_info(file_path: str) -> List[Dict[str, object]]:
    try:
        midi_file = mido.MidiFile(file_path)
    except IOError:
        return ""Error: The file could not be opened or is not a valid MIDI file.""

    if not midi_file.type in [mido.FileType.stream, mido.FileType.multi_track]:
        return ""Error: The file is not a valid MIDI file.""

    extracted_info = []

    for i, track in enumerate(midi_file.tracks):
        track_info = {
            'track': i + 1,
            'tempo': None,
            'time_signatures': [],
            'key_signatures': []
        }

        current_tempo = 500000  # Default MIDI tempo (microseconds per beat)
        for msg in track:
            if msg.is_meta:
                if msg.type == 'set_tempo':
                    current_tempo = msg.tempo
                    track_info['tempo'] = current_tempo

                elif msg.type == 'time_signature':
                    track_info['time_signatures'].append({
                        'nn': msg.numerator,
                        'dd': msg.denominator,
                        'cc': msg.clocks_per_click,
                        'bb': msg.notated_32nd_notes_per_beat
                    })

                elif msg.type == 'key_signature':
                    track_info['key_signatures'].append({
                        'sf': -1 if msg.key >= 0 else 1,  # Scale is major or minor
                        'mi': abs(msg.key)  # Number of flats (if negative) or sharps (if positive)
                    })

        extracted_info.append(track_info)

    return extracted_info

# Example usage:
