import os
import hmac
import hashlib
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.exceptions import InvalidTag

def generate_hashed_secret(password: str, salt: bytes) -> bytes:
    if not password or len(password) > 512:
        raise ValueError(""Invalid password length"")

    if not salt or len(salt) != hashlib.sha256().digest_size:
        raise ValueError(""Salt must be a valid SHA-256 hash"")

    hmac_sha256 = hmac.new(password.encode(), digestmod=hashlib.sha256)
    hmac_sha256.update(salt)
    secret = hmac_sha256.digest()

    return secret

def generate_master_key(master_password: str, num_keys: int) -> list:
    if not master_password or len(master_password) > 512:
        raise ValueError(""Invalid master password length"")

    salts = [os.urandom(32) for _ in range(num_keys)]
    keys = []

    for salt in salts:
        hashed_secret = generate_hashed_secret(master_password, salt)
        keys.append((hashed_secret, salt))

    return keys

def encrypt_data(secret: bytes, data: bytes, associated_data: bytes, iv: bytes) -> (bytes, bytes):
    if len(iv) != 12:
        raise ValueError(""IV must be 12 bytes long"")

    aes_gcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv),
        backend=default_backend()
    ).encryptor()

    aes_gcm.authenticate_additional_data(associated_data)
    ciphertext = aes_gcm.update(data) + aes_gcm.finalize()

    return ciphertext, aes_gcm.tag

def decrypt_data(secret: bytes, ciphertext: bytes, tag: bytes, associated_data: bytes, iv: bytes) -> bytes:
    if len(iv) != 12:
        raise ValueError(""IV must be 12 bytes long"")

    aes_gcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv, tag),
        backend=default_backend()
    ).decryptor()

    aes_gcm.authenticate_additional_data(associated_data)

    try:
        return aes_gcm.update(ciphertext) + aes_gcm.finalize()
    except InvalidTag:
        raise ValueError(""Invalid authentication tag"")

def encrypt_large_data(secret: bytes, data_stream, associated_data: bytes, iv: bytes):
    aes_gcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv),
        backend=default_backend()
    ).encryptor()

    aes_gcm.authenticate_additional_data(associated_data)

    encrypted_chunks = []
    for chunk in data_stream:
        encrypted_chunk = aes_gcm.update(chunk)
        encrypted_chunks.append(encrypted_chunk)

    return b''.join(encrypted_chunks), aes_gcm.finalize()

def decrypt_large_data(secret: bytes, ciphertext_stream, tag: bytes, associated_data: bytes, iv: bytes):
    if len(iv) != 12:
        raise ValueError(""IV must be 12 bytes long"")

    aes_gcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv, tag),
        backend=default_backend()
    ).decryptor()

    aes_gcm.authenticate_additional_data(associated_data)

    decrypted_chunks = []
    for chunk in ciphertext_stream:
        try:
            decrypted_chunk = aes_gcm.update(chunk)
            decrypted_chunks.append(decrypted_chunk)
        except InvalidTag:
            raise ValueError(""Invalid authentication tag"")

    return b''.join(decrypted_chunks) + aes_gcm.finalize()
