```python
# Import necessary packages
import os
import yaml
import json
import pandas as pd
from flask import Flask, request, jsonify, render_template_string
from werkzeug.security import generate_password_hash, check_password_hash
import jwt
from datetime import datetime, timedelta
import sqlite3
import logging
import hashlib
from functools import wraps

# Load configurations from YAML file
def load_config(file='config.yml'):
    with open(file, 'r') as stream:
        return yaml.safe_load(stream)

CONFIG = load_config()

app = Flask(__name__)
app.config['SECRET_KEY'] = CONFIG['secret_key']

# Logging setup
logging.basicConfig(filename='app.log', level=logging.DEBUG,
                    format='%(asctime)s %(levelname)s:%(message)s')

# Database connection
def get_db_connection():
    conn = sqlite3.connect('data.db')
    conn.row_factory = sqlite3.Row
    return conn

# Create table if not exists
def create_tables():
    conn = get_db_connection()
    with conn:
        conn.execute('''CREATE TABLE IF NOT EXISTS data (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        content TEXT NOT NULL)''')
    conn.close()

create_tables()

# JWT token required decorator for protected routes
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=[""HS256""])
            current_user = data['user']
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        return f(current_user, *args, **kwargs)
    return decorated

# User authentication route
@app.route('/login', methods=['POST'])
def login():
    auth = request.authorization
    if not auth or not auth.username or not auth.password:
        return jsonify({'message': 'Could not verify'}), 401
    user = {'username': 'admin', 'password': generate_password_hash('admin')}
    if check_password_hash(user['password'], auth.password):
        token = jwt.encode(
            {'user': auth.username, 'exp': datetime.utcnow() + timedelta(minutes=30)},
            app.config['SECRET_KEY'],
            algorithm=""HS256""
        )
        return jsonify({'token': token})
    return jsonify({'message': 'Could not verify'}), 401

# Function to handle file uploads and processing
def process_file(file):
    if pd.io.common.file_extension(file.filename) == 'csv':
        data = pd.read_csv(file, chunksize=1000)
    elif pd.io.common.file_extension(file.filename) in ['xls', 'xlsx']:
        data = pd.read_excel(file, chunksize=1000)
    else:
        with open(file.filename, 'r') as f:
            json_data = json.load(f)
            for row in json_data:
                yield row
    return data

# Route to upload and process files
@app.route('/upload', methods=['POST'])
@token_required
def upload_file(current_user):
    if 'file' not in request.files:
        logging.warning('No file part')
        return jsonify({'message': 'No file part'}), 400
    file = request.files['file']
    data_chunks = process_file(file)
    conn = get_db_connection()
    with conn:
        for chunk in data_chunks:
            if isinstance(chunk, pd.DataFrame):
                for _, row in chunk.iterrows():
                    conn.execute('INSERT INTO data (content) VALUES (?)', (json.dumps(row.to_dict()),))
            else:
                conn.execute('INSERT INTO data (content) VALUES (?)', (json.dumps(chunk),))
    return jsonify({'message': 'File processed and saved to database'})

# Route for HTML generation
@app.route('/data')
@token_required
def get_data(current_user):
    conn = get_db_connection()
    cur = conn.cursor()
    cur.execute('SELECT content FROM data LIMIT 10')
    rows = cur.fetchall()
    html_content = ""<html><body><h1>Data</h1>""
    for row in rows:
        html_content += f""<p>{row['content']}</p>""
    html_content += ""</body></html>""
    return render_template_string(html_content)

# Cache decorator
def cache(func):
    cache_dict = {}
    def wrapper(*args, **kwargs):
        key = hashlib.sha256(json.dumps([args, kwargs]).encode()).hexdigest()
        if key in cache_dict:
            logging.info('Cache hit')
            return cache_dict[key]
        result = func(*args, **kwargs)
        cache_dict[key] = result
        logging.info('Cache miss - storing new data')
        return result
    return wrapper

@app.route('/cached_data', methods=['GET'])
@token_required
def get_cached_data(current_user):
    @cache
    def fetch_data():
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute('SELECT content FROM data LIMIT 10')
        rows = cur.fetchall()
        return [row['content'] for row in rows]

    data = fetch_data()
    html_content = ""<html><body><h1>Cached Data</h1>""
    for item in data:
        html_content += f""<p>{item}</p>""
    html_content += ""</body></html>""
    return render_template_string(html_content)

# Interactive console mode
def console_mode():
    while True:
        command = input(""Enter command (exit to quit): "")
        if command == 'exit':
            break
        elif command.startswith('load'):
            filename = command.split()[1]
            data_chunks = process_file(filename)
            conn = get_db_connection()
            with conn:
                for chunk in data_chunks:
                    if isinstance(chunk, pd.DataFrame):
                        for _, row in chunk.iterrows():
                            conn.execute('INSERT INTO data (content) VALUES (?)', (json.dumps(row.to_dict()),))
        elif command == 'show':
            conn = get_db_connection()
            cur = conn.cursor()
            cur.execute('SELECT content FROM data LIMIT 10')
            rows = cur.fetchall()
            print(""\n"".join([row['content'] for row in rows]))
        else:
            print(""Unknown command"")

if __name__ == '__main__':
    console_mode() # For interactive mode
    app.run(debug=True)

# Run unit tests with pytest if necessary, ensure to add test functions
