def load_data_in_chunks(file_path, chunk_size=1000):
    if file_path.endswith('.csv') or file_path.endswith('.xlsx'):
        for chunk in pd.read_csv(file_path, chunksize=chunk_size) if file_path.endswith('.csv') else pd.read_excel(file_path, chunksize=chunk_size):
            yield chunk.to_dict(orient='records')
    elif file_path.endswith('.json'):
        with open(file_path) as f:
            data = json.load(f)
            for i in range(0, len(data), chunk_size):
                yield data[i:i + chunk_size]
    else:
        raise ValueError(""Unsupported file format"")

