```python
import json
import hashlib

def checkJSON(json_string):
    if not isinstance(json_string, str) or not json_string:
        return False

    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        return False

    required_fields = [""name"", ""age"", ""email""]

    for field in required_fields:
        if field not in data or not data[field]:
            return False

    return True

def generateUserHash(json_string):
    if not checkJSON(json_string):
        print(""Invalid JSON input."")
        return """"

    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        return """"

    name = data[""name""]
    hash_object = hashlib.sha256(name.encode())
    return hash_object.hexdigest()
```

- `checkJSON`: Validates the presence and non-empty values of ""name"", ""age"", and ""email"".
