from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes

def generateHashedSecret(password, salt):
    try:
        hashed_secret = hmac.new(salt.encode(), password.encode(), hashlib.sha256).digest()
        return hashed_secret[:32]  # Ensure it is of size suitable for AES key (e.g., 256 bits)
    except Exception as e:
        logging('error', str(e))
        raise

def encryptData(key, data, ad, iv):
    try:
        cipher = AES.new(key, AES.MODE_GCM, nonce=iv)
        cipher.update(ad.encode())
        ciphertext, tag = cipher.encrypt_and_digest(data.encode())
        return (ciphertext, tag)
    except Exception as e:
        logging('error', str(e))
        raise

def generateMasterKey(master_password):
    try:
        salts = [get_random_bytes(16) for _ in range(3)]  # Example: Generate 3 different salts
        secrets = [generateHashedSecret(master_password, salt.hex()) for salt in salts]
        return secrets
    except Exception as e:
