        raise ValueError(""Salt must be 16 bytes."")

    if iv and (not isinstance(iv, (bytes, str)) or len(iv) != 12):
        logging('error', 'Invalid IV')
        raise ValueError(""IV must be 12 bytes for AES-GCM."")

def checkKeySize(key):
