        logging('error', 'Invalid Key Size')
        raise ValueError(""Key size must be 128, 192, or 256 bits."")

def decryptData(encrypted_message, tag, iv, key):
    try:
        cipher = AES.new(key, AES.MODE_GCM, nonce=iv)
        data = cipher.decrypt_and_verify(encrypted_message, tag)
        return data.decode()
    except Exception as e:
        logging('error', str(e))
        raise

def handleLargeData(data_chunks, key, ad='', iv=None):
    try:
        if not iv:
            iv = get_random_bytes(12)  # Generate IV for the first chunk

        cipher = AES.new(key, AES.MODE_GCM, nonce=iv)
        cipher.update(ad.encode())

        encrypted_data = b''
        tags = []

        for chunk in data_chunks:
            ciphertext, tag = cipher.encrypt_and_digest(chunk.encode())
            encrypted_data += ciphertext
            tags.append(tag)

            # Reset cipher context to encrypt next chunk
            cipher = AES.new(key, AES.MODE_GCM, nonce=iv)
            cipher.update(ad.encode())

        return (encrypted_data, tags)
    except Exception as e:
        logging('error', str(e))
        raise

def addRandomness(salt_generator):
