import sys
import json

def parse_log_file(file_path):
    try:
        with open(file_path, 'r') as file:
            data = []
            for line in file:
                parts = line.strip().split()
                if len(parts) >= 4:  # Assuming format: src_ip dest_ip protocol size
                    record = {
                        ""src_ip"": parts[0],
                        ""dest_ip"": parts[1],
                        ""protocol"": parts[2],
                        ""size"": int(parts[3])
                    }
                    data.append(record)
            return data
    except Exception as e:
        print(f""Error reading file {file_path}: {e}"")
        sys.exit(1)

def main():
    if len(sys.argv) != 3:
        print(""Usage: python parse_logs.py -s <input_file> -o <output_json>"")
        sys.exit(1)

    input_file = None
    output_file = None

    for i in range(1, len(sys.argv), 2):
        if sys.argv[i] == '-s':
            input_file = sys.argv[i + 1]
        elif sys.argv[i] == '-o':
            output_file = sys.argv[i + 1]

    if not input_file or not output_file:
        print(""Missing required arguments."")
        sys.exit(1)

    parsed_data = parse_log_file(input_file)

    with open(output_file, 'w') as outfile:
        json.dump(parsed_data, outfile)

if __name__ == ""__main__"":
    main()
