    def generate_tokens(self, count: int) -> List[dict]:
        for _ in range(count):
            token_data = {
                ""random_string"": self._generate_random_string(),
                ""timestamp"": time.time(),
                ""hmac_secret_key"": self._generate_hmac_secret_key()
            }
            self.tokens.append(token_data)
        return self.tokens

    def _generate_random_string(self, length: int = 16) -> str:
        return ''.join(os.urandom(1).hex() for _ in range(length // 2))

    def _generate_hmac_secret_key(self, size: int = 32) -> bytes:
        return os.urandom(size)

