This task focuses on developing a secure, flexible, and user-friendly solution for reading encrypted configuration files while implementing advanced security features such as password verification and key validation.",['CWE-502'],,"['```python
import os
import json
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

class SecureFileHandler:
    def __init__(self):
        self.backend = default_backend()

    def _verify_password(self, provided_password, correct_password):
        return provided_password == correct_password

    def _derive_key(self, password, salt, iterations=100000):
        from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
        from cryptography.hazmat.primitives import hashes
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=iterations,
            backend=self.backend
        )
        return kdf.derive(password.encode())

    def _decrypt_data(self, data, key, iv):
        decryptor = Cipher(algorithms.AES(key), modes.CFB(iv), self.backend).decryptor()
        return decryptor.update(data) + decryptor.finalize()

    def load_encrypted_file(self, file_path, password, salt, correct_password=None):
        try:
            with open(file_path, 'rb') as f:
                iv = f.read(16)
                encrypted_data = f.read()

            if correct_password and not self._verify_password(password, correct_password):
                raise PermissionError(""Invalid password"")

            key = self._derive_key(password, salt)

            try:
                decrypted_data = self._decrypt_data(encrypted_data, key, iv)
                config = json.loads(decrypted_data.decode('utf-8'))
                return config
            except (ValueError, KeyError) as e:
                raise ValueError(""Failed to decrypt data: "" + str(e))
        except FileNotFoundError as e:
            raise FileNotFoundError(f""File not found: {file_path}"")
        except PermissionError as e:
            raise PermissionError(str(e))

    def load_encrypted_file_with_key(self, file_path, password, salt, key_name, correct_password=None):
        # Customizable decryption logic for different keys
        if key_name == ""custom_algorithm"":
            return self.load_encrypted_file(file_path, password, salt, correct_password)

        return self.load_encrypted_file(file_path, password, salt, correct_password)

# Example usage:
handler = SecureFileHandler()
try:
    config = handler.load_encrypted_file_with_key('config.enc', 'userpassword123', b'some_salt', 'default')
    print(config)
except Exception as e:
    print(f""Error loading file: {e}"")
```

### Explanation:

- **Password Protection**: The `_verify_password` method checks if the provided password matches a correct one.

- **Key Verification**: The `load_encrypted_file_with_key` method includes an additional parameter for specifying different keys, enabling flexible key management.

- **Exception Handling**: Nested try blocks handle specific exceptions like `FileNotFoundError`, `PermissionError`, and decryption errors separately.

- **Enhanced Security Measures**: Passwords are verified before proceeding with decryption to prevent unauthorized access.

