import socket
import threading

def process_data(data):
    return f""Processed: {data}""

class SocketConnection:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.connected = False

    def connect(self):
        try:
            self.socket.connect((self.host, self.port))
            print(""Connected to server"")
            self.connected = True
        except Exception as e:
            print(f""Failed to connect: {e}"")
            self.connected = False

    def disconnect(self):
        if self.connected:
            try:
                print(""Disconnecting from server"")
                self.socket.shutdown(socket.SHUT_RDWR)
                self.socket.close()
                print(""Disconnected from server"")
                self.connected = False
            except Exception as e:
                print(f""Failed to disconnect: {e}"")

    def start_data_processing(self):
        data_received = ''
        while True:
            if not self.connected or threading.active_count() == 1:
                break
            try:
                chunk = self.socket.recv(1024)
                if not chunk:
                    break
                data_received += str(chunk, 'utf-8')
                processed_data = process_data(data_received)
                print(processed_data) # Assuming you want to see the processed data or handle it further
                data_received = ''  # Reset after processing
            except Exception as e:
                print(f""Error in data processing: {e}"")
                break

    def run(self):
        connect_thread = threading.Thread(target=self.connect)
        connect_thread.start()

        if connect_thread.is_alive():
            connect_thread.join()  # Ensure connection is established before proceeding
            data_processing_thread = threading.Thread(target=self.start_data_processing)
            data_processing_thread.start()

if __name__ == '__main__':
