        self.min = min_val
        self.max = max_val

    def generate_float(self) -> float:
        return random.uniform(self.min, self.max)

    def generate_int(self) -> int:
        return round(self.generate_float())

    def __str__(self):
        return f""CustomRandomGenerator(min={self.min}, max={self.max})""
