# Load the C++ shared library
lib = ctypes.CDLL('./dns_resolver.so')

def get_ip_address(hostname):
    lib.resolveDNS.argtypes = [ctypes.c_char_p]
    lib.resolveDNS.restype = ctypes.c_char_p
    return lib.resolveDNS(hostname.encode('utf-8')).decode('utf-8')

class ObjectManager:
    def __init__(self):
        self.objects = {}

    def create_object(self, object_id, data):
        obj_data = json.loads(data)
        ip_address = get_ip_address(obj_data['hostname'])
        if ip_address:
            obj_data['ip_address'] = ip_address
        self.objects[object_id] = obj_data

    def get_object(self, object_id):
        return self.objects.get(object_id, None)

# Example usage
