import random
import threading
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_flag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_flag = crc_flag

def generate_random_value(min_val, max_val):
    return random.randint(min_val, max_val)

def validate_rx_ue_information_tag(tag):
    # Example validation logic for RX_UE_INFORMATION_TAG
    return 0 <= tag <= 255

def validate_rnti(rnti):
    # Example validation logic for RNTI
    return rnti % 2 == 0

def generate_and_validate():
    try:
        rx_ue_information_tag = generate_random_value(0, 255)
        if not validate_rx_ue_information_tag(rx_ue_information_tag):
            raise ValueError(f""Invalid RX_UE_INFORMATION_TAG: {rx_ue_information_tag}"")

        rnti = generate_random_value(1, 65535)
        if not validate_rnti(rnti):
            raise ValueError(f""Invalid RNTI: {rnti}"")

        crc_flag = generate_random_value(0, 1)

        logging.info(f'Generated PDU: RX_UE_INFORMATION_TAG={rx_ue_information_tag}, '
                     f'RNTI={rnti}, CRC_FLAG={crc_flag}')

        return NFAPI_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_flag)

    except Exception as e:
        logging.error(f'Error during generation/validations: {e}')

def worker(num_structures):
    structures = []
    for _ in range(num_structures):
        structure = generate_and_validate()
        if structure:
            structures.append(structure)
    return structures

def create_structures_concurrently(num_structures, num_threads=4):
    threads = []
    results = []

    def thread_function(thread_id):
        result = worker(num_structures // num_threads)
        results.extend(result)

    for i in range(num_threads):
        t = threading.Thread(target=thread_function, args=(i,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return results

def main():
    # Configurable parameters
    num_structures_to_create = 10
    num_threads = 4

    structures = create_structures_concurrently(num_structures_to_create, num_threads)

if __name__ == ""__main__"":
    main()
