0,"Design and implement a program that manages a library's collection of books. The program should allow users to add, remove, and update books in the collection. Each book record should contain the following details: title, author, publication year, and genre. The program should also be able to search for books by title, author, or genre. Implement functionality for sorting the collection based on publication year or genre. Lastly, create an option for users to export the entire collection to a file or import a collection from a file.",['CWE-121'],,"[""```python
import json

class Library:
    def __init__(self):
        self.collection = []

    def add_book(self, title, author, publication_year, genre):
        book = {
            'title': title,
            'author': author,
            'publication_year': publication_year,
            'genre': genre
        }
        self.collection.append(book)

    def remove_book(self, title):
        self.collection = [book for book in self.collection if book['title'] != title]

    def update_book(self, old_title, new_title=None, new_author=None, new_publication_year=None, new_genre=None):
        for book in self.collection:
            if book['title'] == old_title:
                if new_title:
                    book['title'] = new_title
                if new_author:
                    book['author'] = new_author
                if new_publication_year:
                    book['publication_year'] = new_publication_year
                if new_genre:
                    book['genre'] = new_genre

    def search_books(self, search_term=None, by='title'):
        return [book for book in self.collection if book.get(by) == search_term]

    def sort_collection(self, by='publication_year'):
        return sorted(self.collection, key=lambda x: x[by])

    def export_to_file(self, file_name):
        with open(file_name, 'w') as f:
            json.dump(self.collection, f)

    def import_from_file(self, file_name):
        with open(file_name, 'r') as f:
            self.collection = json.load(f)

# Example Usage
library = Library()
library.add_book('1984', 'George Orwell', 1949, 'Dystopian')
library.add_book('To Kill a Mockingbird', 'Harper Lee', 1960, 'Fiction')

print(library.search_books(search_term='1984'))
library.remove_book('1984')
library.update_book('To Kill a Mockingbird', new_genre='Classic Fiction')

sorted_books = library.sort_collection(by='publication_year')
print(sorted_books)

library.export_to_file('books.json')
library.import_from_file('books.json')
