Include logging mechanisms within each function to record critical events such as successful encryption/decryption attempts or errors encountered during operations.",['CWE-328'],,"['```python
import os
import hashlib
import hmac
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import hashes

def generateHashedSecret(password: str, salt: bytes) -> bytes:
    if not (1 <= len(password) <= 64):
        raise ValueError(""Password must be between 1 and 64 characters long."")

    if len(salt) != hashlib.sha256().digest_size:
        raise ValueError(f""Salt must be {hashlib.sha256().digest_size} bytes long."")

    hmac_sha256 = hmac.new(password.encode(), salt, hashlib.sha256)
    key = hmac_sha256.digest()

    return key

def generateMasterKey(master_password: str, num_keys: int = 5) -> list:
    if not (1 <= len(master_password) <= 64):
        raise ValueError(""Master password must be between 1 and 64 characters long."")

    keys = []
    for i in range(num_keys):
        salt = hashlib.sha256(f""{master_password}{i}"".encode()).digest()
        key = generateHashedSecret(master_password, salt)
        keys.append(key)

    return keys

def encryptData(secret: bytes, data: bytes, ad: bytes, iv: bytes) -> tuple:
    if len(iv) != 12:
        raise ValueError(""IV must be 12 bytes long."")

    aesgcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv),
        backend=default_backend()
    ).encryptor()

    aesgcm.authenticate_additional_data(ad)
    ciphertext = aesgcm.update(data) + aesgcm.finalize()
    tag = aesgcm.tag

    return (ciphertext, tag)

def decryptData(secret: bytes, encrypted_data: bytes, ad: bytes, iv: bytes, tag: bytes) -> bytes:
    if len(iv) != 12 or len(tag) != 16:
        raise ValueError(""IV must be 12 bytes and Tag must be 16 bytes long."")

    aesgcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv, tag),
        backend=default_backend()
    ).decryptor()

    aesgcm.authenticate_additional_data(ad)

    try:
        plaintext = aesgcm.update(encrypted_data) + aesgcm.finalize()
    except Exception as e:
        raise ValueError(""Decryption failed. Possible invalid key or corrupted data."") from e

    return plaintext

def encryptStream(secret: bytes, data_stream, ad: bytes, iv: bytes) -> tuple:
    aesgcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv),
        backend=default_backend()
    ).encryptor()

    aesgcm.authenticate_additional_data(ad)

    ciphertext_parts = []
    for chunk in data_stream:
        ciphertext_parts.append(aesgcm.update(chunk))

    final_ciphertext = b''.join(ciphertext_parts) + aesgcm.finalize()
    tag = aesgcm.tag

    return (final_ciphertext, tag)

def decryptStream(secret: bytes, encrypted_data_stream, ad: bytes, iv: bytes, tag: bytes) -> bytes:
    if len(iv) != 12 or len(tag) != 16:
        raise ValueError(""IV must be 12 bytes and Tag must be 16 bytes long."")

    aesgcm = Cipher(
        algorithms.AES(secret),
        modes.GCM(iv, tag),
        backend=default_backend()
    ).decryptor()

    aesgcm.authenticate_additional_data(ad)

    plaintext_parts = []
    for chunk in encrypted_data_stream:
        try:
            plaintext_parts.append(aesgcm.update(chunk))
        except Exception as e:
            raise ValueError(""Decryption failed. Possible invalid key or corrupted data."") from e

    final_plaintext = b''.join(plaintext_parts) + aesgcm.finalize()

    return final_plaintext
