import time
import os
import logging

# Setup logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class InvalidLinkIdException(Exception):
    pass

class DynamicLink:
    def __init__(self, LINK_ID, TIMESTAMP, HMAC_SECRET_KEY):
        self.LINK_ID = LINK_ID
        self.TIMESTAMP = TIMESTAMP
        self.HMAC_SECRET_KEY = HMAC_SECRET_KEY

def create_dynamic_links(LINK_IDS=None, max_links=100, secret_key_length=32):
    if LINK_IDS is None:
        LINK_IDS = [f""ID_{i}"" for i in range(max_links)]

    if not all(isinstance(link_id, str) and link_id.isidentifier() for link_id in LINK_IDS):
        raise InvalidLinkIdException(""All LINK_IDs must be valid identifiers."")

    unique_link_ids = set()
    dynamic_links = []

    for link_id in LINK_IDS:
        if len(unique_link_ids) >= max_links:
            break

        if not isinstance(link_id, str) or not link_id.isidentifier():
            logging.error(f""Invalid LINK_ID: {link_id}"")
            raise InvalidLinkIdException(f""Invalid LINK_ID: {link_id}"")

        if link_id in unique_link_ids:
            logging.error(f""Duplicate LINK_ID detected: {link_id}"")
            raise InvalidLinkIdException(f""Duplicate LINK_ID detected: {link_id}"")

        try:
            # Generate a cryptographically strong HMAC secret key
            secret_key = os.urandom(secret_key_length)
        except Exception as e:
            logging.error(f""HMAC Secret Key generation failed for {link_id}: {e}"")
            continue

        timestamp = time.time()
        dynamic_links.append(DynamicLink(link_id, timestamp, secret_key))
        unique_link_ids.add(link_id)

    # Final check to verify all generated links meet specific criteria
    if len(dynamic_links) != len(set(dl.LINK_ID for dl in dynamic_links)):
        raise Exception(""Generated LINK_IDs are not unique."")

    if any(not (timestamp > time.time() - 1 and timestamp < time.time() + 1) for _, timestamp, _ in dynamic_links):
        raise Exception(""TIMESTAMP is out of valid range."")

    logging.info(f""Successfully generated {len(dynamic_links)} links"")
    return dynamic_links

# Unit Tests
def test_create_dynamic_links():
    # Test with invalid LINK_ID inputs
    try:
        create_dynamic_links(['123', 'invalid-link'])
    except InvalidLinkIdException as e:
        assert str(e) == ""Invalid LINK_ID: 123""

    # Test with duplicate LINK_IDs within one execution of the function
    try:
        create_dynamic_links(['ID_1', 'ID_2', 'ID_1'])
    except InvalidLinkIdException as e:
        assert str(e) == ""Duplicate LINK_ID detected: ID_1""

    # Test scenarios where HMAC key generation fails (simulate by reducing available entropy)
    try:
        original_urandom = os.urandom
        os.urandom = lambda x: b'\x00' * x  # Simulate low entropy
        create_dynamic_links(max_links=10, secret_key_length=1)
    except Exception as e:
        assert ""HMAC Secret Key generation failed"" in str(e)
    finally:
        os.urandom = original_urandom

    # Test with extremely large values for max_links
    try:
        links = create_dynamic_links(['ID_{}'.format(i) for i in range(1000)], max_links=1000)
        assert len(links) == 1000
    except Exception as e:
        print(f""Test failed: {e}"")

    # Test with zero or negative values for secret_key_length
    try:
        create_dynamic_links(secret_key_length=-1)
    except ValueError:
        pass

    # Test with non-integer values for max_links and secret_key_length
    try:
        create_dynamic_links(max_links='100')
    except TypeError:
        pass

    try:
        create_dynamic_links(secret_key_length=32.5)
    except TypeError:
        pass

    print(""All tests passed."")

# Run unit tests
test_create_dynamic_links()
