import argparse
import os
import fnmatch
from collections import Counter

def count_text_files(directory, exclude_patterns=None):
    text_file_count = 0
    file_extension_counter = Counter()

    if exclude_patterns is None:
        exclude_patterns = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            if not any(fnmatch.fnmatch(file, pattern) for pattern in exclude_patterns):
                if file.endswith('.txt'):
                    text_file_count += 1
                    file_extension_counter['.txt'] += 1

    return text_file_count, file_extension_counter

def main():
    parser = argparse.ArgumentParser(description='Count all text files recursively within a directory.')
    parser.add_argument('--version', action='store_true', help='Display program version information')
    parser.add_argument('-d', '--directory', type=str, required=False, help='Specify a directory to traverse')
    parser.add_argument('-e', '--exclude-patterns', type=str, nargs='+', default=[], help='Patterns to exclude from counting')

    args = parser.parse_args()

    if args.version:
        print('Version 2.0')  # Implement your version information here

    elif not args.directory:
        print('Usage: python script.py -d /path/to/directory')

    else:
        try:
            total_text_files, file_extensions = count_text_files(args.directory, args.exclude_patterns)
            print(f'Total text files found: {total_text_files}')
            print('File extensions found:')
            for ext in sorted(file_extensions.keys()):
                print(f'{ext}: {file_extensions[ext]}')

        except Exception as e:
            print(f'Error: {e}')

if __name__ == '__main__':
    main()
