# Models
class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(150), unique=True, nullable=False)
    password_hash = db.Column(db.String(150), nullable=False)
    social_id = db.Column(db.String(150), nullable=True)

class DocumentFolder(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    owner_id = db.Column(db.Integer, db.ForeignKey('user.id'))
    users = db.relationship('User', secondary='folder_access')

class FolderAccess(db.Model):
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), primary_key=True)
    folder_id = db.Column(db.Integer, db.ForeignKey('document_folder.id'), primary_key=True)

class DocumentVersion(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.Text, nullable=False)
    document_id = db.Column(db.Integer, db.ForeignKey('document.id'))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'))

class Document(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    folder_id = db.Column(db.Integer, db.ForeignKey('document_folder.id'))
    current_version_id = db.Column(db.Integer, db.ForeignKey('document_version.id'))

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        email = request.form['email']
        password = generate_password_hash(request.form['password'], method='sha256')
        new_user = User(email=email, password_hash=password)
        db.session.add(new_user)
        db.session.commit()
        return redirect(url_for('login'))
    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        user = User.query.filter_by(email=request.form['email']).first()
        if user and check_password_hash(user.password_hash, request.form['password']):
            login_user(user)
            return redirect(url_for('dashboard'))
    return render_template('login.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/')
def index():
    return 'Welcome to the Document Collaboration Platform!'

@app.route('/dashboard')
@login_required
def dashboard():
    folders = DocumentFolder.query.filter_by(owner_id=current_user.id).all()
    return render_template('dashboard.html', folders=folders)

@socketio.on('edit_document')
def handle_edit(json):
    # Handle real-time document editing logic here
    emit('document_update', json, broadcast=True)

# Unit tests (example for registration)
def test_registration():
    tester = app.test_client()
    response = tester.post('/register', data=dict(email='test@example.com', password='password'), follow_redirects=True)
    assert b'Registered successfully' in response.data

# Run the application
if __name__ == '__main__':
    db.create_all()
    socketio.run(app, debug=True)

