# Define the MAC_SDU_T structure
class MAC_SDU_T:
    def __init__(self):
        self.source_address = """"
        self.destination_address = """"
        self.data_field = """"

def generate_random_mac():
    """"""Generate a random MAC address.""""""
    return "":"".join(f""{random.randint(0, 255):02x}"" for _ in range(6))

def generate_random_data(length=64):
    """"""Generate random data of given length.""""""
    return ''.join(chr(random.randint(32, 126)) for _ in range(length))

def generate_mac_sdu_list(count):
    """"""Generate a list of MAC_SDU_T structures with random content.""""""
    mac_sdu_list = []
    for _ in range(count):
        mac_sdu = MAC_SDU_T()
        mac_sdu.source_address = generate_random_mac()
        mac_sdu.destination_address = generate_random_mac()
        mac_sdu.data_field = generate_random_data()
        mac_sdu_list.append(mac_sdu)
    return mac_sdu_list

# Example usage
if __name__ == ""__main__"":
    random.seed(time.time())  # Seed for randomness based on current time
    sdu_list = generate_mac_sdu_list(5)
    for sdu in sdu_list:
        print(f""Source: {sdu.source_address}, Destination: {sdu.destination_address}, Data: {sdu.data_field}"")
