import base64
import hashlib
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15
from Crypto.Hash import SHA256, SHA384, SHA512

class DigitalSignatureVerifier:
    def __init__(self, public_key_path=None):
        if public_key_path:
            try:
                self.public_key = RSA.import_key(open(public_key_path).read())
            except (ValueError, FileNotFoundError) as e:
                print(f""Failed to load public key: {str(e)}"")
                self.public_key = None
        else:
            self.public_key = None

    def verify_signature(self, message, signature, hash_algorithm=""SHA256"", signature_format=""base64""):
        if not self.public_key:
            return False

        try:
            if signature_format == ""base64"":
                signature = base64.b64decode(signature)
            else:
                raise ValueError(""Invalid signature format"")

            hash_obj = self.get_hash_object(hash_algorithm, message)
            try:
                pkcs1_15.new(self.public_key).verify(hash_obj, signature)
                return True
            except (ValueError, TypeError):
                print(""Signature verification failed: Invalid signature or key."")
                return False

        except FileNotFoundError:
            print(""Public key file not found."")
        except Exception as e:
            print(f""An error occurred during verification: {str(e)}"")

    def get_hash_object(self, algorithm_name, message):
        if algorithm_name == ""SHA256"":
            return SHA256.new(message.encode('utf-8'))
        elif algorithm_name == ""SHA384"":
            return SHA384.new(message.encode('utf-8'))
        elif algorithm_name == ""SHA512"":
            return SHA512.new(message.encode('utf-8'))
        else:
            raise ValueError(""Unsupported hash algorithm specified"")

    def generate_signature(self, private_key_path, message, hash_algorithm=""SHA256""):
        try:
            with open(private_key_path) as key_file:
                private_key = RSA.import_key(key_file.read())

            signature_obj = pkcs1_15.new(private_key)
            hash_obj = self.get_hash_object(hash_algorithm, message)
            signature = signature_obj.sign(hash_obj)
            return base64.b64encode(signature).decode('utf-8')

        except (ValueError, FileNotFoundError) as e:
            print(f""Failed to generate signature: {str(e)}"")
            return None

def main():
    verifier = DigitalSignatureVerifier('public.pem')

    # Incorrect public key file path scenario
    try:
        result = verifier.verify_signature(""This is a test message"", ""bad_signature"")
        if not result:
            print(""Verification failed."")
    except FileNotFoundError as e:
        print(e)

    # Invalid signature format scenario
    try:
        result = verifier.verify_signature(""This is a test message"", ""bad_signature"", hash_algorithm=""SHA256"", signature_format=""invalid_format"")
        if result is None:
            print(""Verification failed due to invalid format."")
    except ValueError as e:
        print(e)

if __name__ == ""__main__"":
    main()
```

