import random
import csv

class Employee:
    def __init__(self, name, position, salary):
        self.name = name
        self.position = position
        self.salary = salary

def generate_employees(num_employees):
    names = [""Alice"", ""Bob"", ""Charlie"", ""David"", ""Eve""]
    positions = [""Developer"", ""Designer"", ""Manager"", ""Analyst"", ""Tester""]

    employees = []
    for _ in range(num_employees):
        name = random.choice(names)
        position = random.choice(positions)
        salary = random.randint(50000, 150000) # Example range
        employee = Employee(name, position, salary)
        employees.append(employee)

    return employees

def ternary_search(arr, x):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == x:
            return mid1
        if arr[mid2] == x:
            return mid2

        if x < arr[mid1]:
            right = mid1 - 1
        elif x > arr[mid2]:
            left = mid2 + 1
        else:
            left, right = mid1 + 1, mid2 - 1

    return -1

def load_ratings(filename):
    ratings = {}

    with open(filename, mode='r') as file:
        csv_reader = csv.DictReader(file)

        for row in csv_reader:
            name = row[""employee_name""]
            score = int(row[""score""])

            if name not in ratings:
                ratings[name] = []

            ratings[name].append(score)

    return {k: v[:100] for k, v in ratings.items()}

class PerformanceModel:
    def __init__(self, kpis):
        self.kpis = kpis

def evaluate_performance(employees, ratings):
    performance_models = {}

    for employee in employees:
        name = employee.name
        scores = ratings.get(name, [])

        if scores:
            optimal_kpi_index = ternary_search(scores, max(scores))
            # Example: Use the highest KPI score as an indicator of performance
            kpis = [scores[optimal_kpi_index]] 
            performance_model = PerformanceModel(kpis)

            performance_models[employee.name] = performance_model

    return performance_models

