import random
import threading
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_flag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_flag = crc_flag

def generate_random_value(min_val, max_val):
    return random.randint(min_val, max_val)

def verify_rx_ue_info(rx_ue_information_tag, rnti):
    # Placeholder for verification logic: e.g., specific bit checks or value range conditions
    return (0x0001 <= rx_ue_information_tag <= 0xFFFF) and (0x01 <= rnti <= 0xFF)

def handle_error(error_message):
    logging.error(f""Error occurred: {error_message}"")

def generate_pdu(rx_range, rnti_range, crcflag_values, count=1):
    pdus = []
    for _ in range(count):
        try:
            rx_ue_info_tag = generate_random_value(*rx_range)
            rnti = generate_random_value(*rnti_range)
            crc_flag = random.choice(crcflag_values)

            if not verify_rx_ue_info(rx_ue_info_tag, rnti):
                raise ValueError(""Validation failed for generated values"")

            pdu = NFAPI_CRC_INDICATION_PDU_T(rx_ue_info_tag, rnti, crc_flag)
            pdus.append(pdu)

        except Exception as e:
            handle_error(str(e))

    logging.info(f""Generated {len(pdus)} PDU(s)."")
    return pdus

def generate_pdus_concurrently(rx_range, rnti_range, crcflag_values, count=1):
    threads = []
    results = []

    def thread_function():
        result = generate_pdu(rx_range, rnti_range, crcflag_values, count)
        results.extend(result)

    for _ in range(count):
        thread = threading.Thread(target=thread_function)
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    logging.info(f""Total PDU(s) generated concurrently: {len(results)}."")
    return results

# Example usage
if __name__ == ""__main__"":
    rx_range = (0x0001, 0xFFFF)
    rnti_range = (0x01, 0xFF)
    crcflag_values = [True, False]

    pdus = generate_pdus_concurrently(rx_range, rnti_range, crcflag_values, count=5)

    for pdu in pdus:
        logging.info(f""PDU: RX_UE_INFO_TAG={pdu.rx_ue_information_tag}, RNTI={pdu.rnti}, CRC_FLAG={pdu.crc_flag}"")
