import requests
import time
import threading
import jwt
from datetime import datetime, timedelta
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class APIClient:
    def __init__(self, client_id, client_secret, token_url):
        self.client_id = client_id
        self.client_secret = client_secret
        self.token_url = token_url
        self.token_info = None
        self.lock = threading.Lock()

        # Start the background thread to refresh token
        self.refresh_thread = threading.Thread(target=self.refresh_token_periodically)
        self.refresh_thread.daemon = True  # Daemonize thread to exit when main program exits
        self.refresh_thread.start()

    def get_token(self):
        with self.lock:
            if not self.token_info or self.is_token_expired():
                response = requests.post(
                    self.token_url,
                    data={
                        'grant_type': 'client_credentials',
                        'client_id': self.client_id,
                        'client_secret': self.client_secret
                    }
                )

                if response.status_code == 200:
                    self.token_info = response.json()
                    logger.info(""Token retrieved successfully."")
                else:
                    logger.error(f""Failed to retrieve token: {response.text}"")
                    raise Exception(f""Failed to retrieve token: {response.text}"")

            return self.token_info['access_token']

    def is_token_expired(self):
        if not self.token_info:
            return True
        expires_at = datetime.fromtimestamp(self.token_info['expires_at'])
        return datetime.utcnow() >= expires_at - timedelta(minutes=5)  # Refresh 5 minutes before expiry

    def refresh_token_periodically(self):
        while True:
            try:
                if self.is_token_expired():
                    logger.info(""Refreshing token..."")
                    self.get_token()
                time.sleep(60)  # Check every minute
            except Exception as e:
                logger.error(f""Error refreshing token: {e}"")

    def validate_token(self, token):
        try:
            decoded = jwt.decode(token, options={""verify_signature"": False})
            logger.info(""Token validated successfully."")
            return True
        except jwt.ExpiredSignatureError:
            logger.warning(""Token has expired."")
        except Exception as e:
            logger.error(f""Token validation failed: {e}"")

        return False

# Usage example (with placeholders for client_id, client_secret, and token_url)
client = APIClient(client_id='your_client_id', client_secret='your_client_secret', token_url='https://example.com/oauth/token')

try:
    # Simulating API usage
    while True:
        token = client.get_token()
        if client.validate_token(token):
            # Perform authenticated operations with the token
            pass
        time.sleep(10)  # Simulate some work being done with the token

except KeyboardInterrupt:
    logger.info(""Program terminated."")
