class Transaction:
    def __init__(self, id, age, past_transactions, weighted_sum):
        self.id = id
        self.age = age
        self.past_transactions = past_transactions
        self.weighted_sum = weighted_sum

class Metrics:
    def __init__(self):
        self.highest_weighted_sum = float('-inf')
        self.highest_weighted_sum_id = None

def filter_transactions(transactions):
    metrics = Metrics()
    for transaction in transactions:
        if transaction.age > 5.0 and transaction.past_transactions > 10 and transaction.weighted_sum > 50.0:
            if transaction.weighted_sum > metrics.highest_weighted_sum:
                metrics.highest_weighted_sum = transaction.weighted_sum
                metrics.highest_weighted_sum_id = transaction.id
    return metrics

def main():
    transactions = [
        Transaction(1, 6.5, 12, 60),
        Transaction(2, 4.9, 9, 45),
        Transaction(3, 7.2, 13, 75),
        Transaction(4, 8.1, 15, 80),
    ]

    metrics_result = filter_transactions(transactions)

    print(""ID:"", metrics_result.highest_weighted_sum_id)
    print(""Max Weighted Sum:"", metrics_result.highest_weighted_sum)

if __name__ == ""__main__"":
    main()
