import random

class CustomRandomGenerator:
    def __init__(self, minValue, maxValue):
        self.minValue = minValue
        self.maxValue = maxValue
        self.random = random.Random(seed=int(minValue * 1000))

    def GenerateFloat(self, precision=2):
        return round(self.random.uniform(self.minValue, self.maxValue), precision)

    def __str__(self):
        return f""CustomRandomGenerator with range ({self.minValue}, {self.maxValue})""

class AdvancedCustomRandomGenerator(CustomRandomGenerator):
    def __init__(self, minValue, maxValue):
        super().__init__(minValue, maxValue)
        self._rangeDifference = maxValue - minValue
        self._currentMinValue = minValue
        self._previousIntValue = None
        self.minValue = self._currentMinValue
        self.maxValue = self.minValue + self._rangeDifference
        self.random.seed(int(self.minValue * 1000))

    def GenerateFloat(self, precision=2):
        return round(super().GenerateFloat(precision), precision)

    def GenerateInt(self, minValue=None, maxValue=None):
        if minValue is None:
            minValue = self.minValue
        if maxValue is None:
            maxValue = self.maxValue

        generated_value = int(self.GenerateFloat())

        if generated_value < minValue or generated_value > maxValue:
            return self.GenerateInt(minValue, maxValue)

        self._previousIntValue = generated_value
        return generated_value

    def __str__(self):
        base_str = super().__str__()
        additional_info = f"" with previous int value: {self._previousIntValue}""
        return base_str + additional_info

