**Python Code (json_class.py):**

```python
import json
import subprocess

class JsonClass:
    _registry = {}

    def __init__(self, data=None):
        self.data = data if data else {}

    @classmethod
    def register(cls, id_, factory):
        cls._registry[id_] = factory

    @staticmethod
    def resolve_dns(hostname):
        result = subprocess.run(
            [""nslookup"", hostname],
            capture_output=True,
            text=True
        )
        return result.stdout.strip()

    @classmethod
    def fromJsonString(cls, json_string):
        data = json.loads(json_string)
        if 'id' in data and data['id'] in cls._registry:
            factory = cls._registry[data['id']]
            return factory(data)
        return cls(data)

    def toJsonString(self):
        return json.dumps(self.data)

# Example usage of the registry
def create_example_obj(data):
    obj = JsonClass()
    obj.data.update(data)
    return obj

JsonClass.register('example', create_example_obj)
