import concurrent.futures
from typing import Callable, List

class Record:
    def __init__(self, identifier: str, transformation: Callable[[str], str], input_data: str):
        self.identifier = identifier
        self.transformation = transformation
        self.input_data = input_data
        self.output_data = None

def process_record(record: Record) -> None:
    try:
        record.output_data = record.transformation(record.input_data)
    except Exception as e:
        raise ValueError(f""Error processing record {record.identifier}: {e}"")

class RecordManager:
    def __init__(self):
        self.records = []

    def add_record(self, identifier: str, transformation: Callable[[str], str], input_data: str) -> None:
        if not isinstance(identifier, str) or not callable(transformation) or not isinstance(input_data, str):
            raise ValueError(""Invalid record input."")
        new_record = Record(identifier, transformation, input_data)
        self.records.append(new_record)

    def remove_processed_records(self) -> None:
        self.records = [record for record in self.records if record.output_data is None]

    def process_records(self, parallel: bool = False) -> List[str]:
        results = []
        if parallel:
            with concurrent.futures.ThreadPoolExecutor() as executor:
                futures = {executor.submit(process_record, record): record for record in self.records}
                for future in concurrent.futures.as_completed(futures):
                    try:
                        future.result()
                        results.append((futures[future].identifier, futures[future].output_data))
                    except ValueError as e:
                        print(e)
        else:
            for record in self.records:
                try:
                    process_record(record)
                    results.append((record.identifier, record.output_data))
                except ValueError as e:
                    print(e)

        self.remove_processed_records()
        return results

# Example usage
if __name__ == ""__main__"":
    def example_transformation(data: str) -> str:
        return data.upper()

    manager = RecordManager()

    try:
        manager.add_record(""1"", example_transformation, ""hello"")
        manager.add_record(""2"", example_transformation, 123)  # This will raise an error
        manager.add_record(""3"", example_transformation, ""world"")

        results = manager.process_records(parallel=True)
        print(results)
    except ValueError as e:
        print(e)
