                tempo = msg.tempo / 60000000  # Convert to BPM (beats per minute)
            elif msg.type == 'time_signature':
                numerator, denominator = divmod(msg.denominator, 2**msg.numerator)
                time_signature = (numerator * 2**12) / denominator  # Adjusting to standard 12-bit resolution values
            elif msg.type == 'key_signature':
                key_signature = int(msg.key)

        # Extract notes played within specified intervals here

        tracks_info.append({
            'track_id': i,
            'tempo': tempo,
            'time_signature': time_signature,
            'key_signature': key_signature,
            'notes_within_intervals': notes_within_intervals,
        })

    try:
        response = requests.post(api_url, json={'tracks_info': tracks_info})

        if response.status_code == 200:
            return ""API update successful.""
        else:
            return f""Failed to update API. Status Code: {response.status_code}""

    except Exception as e:
         return f""An error occurred while updating the API: {e}""

