# NetworkLogParser.py
import subprocess
import re

class NetworkLogParser:
    def __init__(self, c_resolver):
        self.c_resolver = c_resolver

    def parse_log(self, file_path):
        with open(file_path, 'r') as file:
            for line in file:
                match = re.search(r'SRC: (\S+) DST: (\S+)', line)
                if match:
                    src_ip = match.group(1)
                    dst_ip = match.group(2)

                    try:
                        resolved_src = self.c_resolver.resolveDNS(src_ip)
                        print(f""Resolved Source IP: {resolved_src}"")
                    except Exception as e:
