    def compute_checksum(self, file_content):
        """"""Compute SHA-256 checksum for given content.""""""
        if file_content is not None:
            sha256 = hashlib.sha256()
            sha256.update(file_content)
            return sha256.hexdigest()
        return None

    def generate_and_store_checksum(self, file_path):
        """"""Generate and store the checksum of a file with its path.""""""
        content = self.read_file_content(file_path)
        checksum = self.compute_checksum(content)

        if checksum:
            if checksum not in self.unique_checksums:
                self.checksums.append((file_path, checksum))
                self.unique_checksums.add(checksum)

