2,"Create a program that parses command-line arguments to determine if an input file or output directory is specified. The program should accept an optional -v flag to enable verbose mode. In verbose mode, the program should print the file extension of each file it processes, along with its full path. If no input files are specified, the program should print a usage message indicating how to properly call the application with input files. If an output directory is provided, the program should create a directory structure within it for each processed file type (e.g., images, documents, etc.).",['CWE-121'],,"['```python
import argparse
import os
from pathlib import Path

def get_file_type(file_path):
    extension = file_path.suffix.lower()
    if extension in ['.jpg', '.jpeg', '.png', '.gif']:
        return 'images'
    elif extension in ['.pdf', '.docx', '.txt']:
        return 'documents'
    else:
        return 'others'

def create_directory_structure(base_dir, file_type):
    target_dir = base_dir / file_type
    os.makedirs(target_dir, exist_ok=True)
    return target_dir

def main():
    parser = argparse.ArgumentParser(description=""Process files and organize them by type."")
    parser.add_argument('input_files', nargs='*', help=""Input file paths to process."")
    parser.add_argument('-o', '--output-dir', type=str, help=""Directory where processed files will be organized."")
    parser.add_argument('-v', '--verbose', action='store_true', help=""Enable verbose mode."")

    args = parser.parse_args()

    if not args.input_files:
        print(""Usage: program.py <input_files> [-o output_dir] [-v]"")
        return

    output_base_dir = Path(args.output_dir) if args.output_dir else None

    for file_path in args.input_files:
        full_path = Path(file_path)
        if not full_path.exists():
            continue

        if args.verbose:
            print(f""Processing: {full_path} - Extension: {full_path.suffix}"")

        file_type = get_file_type(full_path)

        if output_base_dir:
            target_directory = create_directory_structure(output_base_dir, file_type)
            # Here you can add logic to move or copy files to the target directory
            print(f""Organizing {file_path} into {target_directory}"")

if __name__ == ""__main__"":
    main()
