import yaml
from jinja2 import Environment, FileSystemLoader

class EmailContentGenerator:
    def __init__(self, config_path):
        self.config = self.load_yaml_config(config_path)
        self.template_env = Environment(loader=FileSystemLoader('templates'))

    def load_yaml_config(self, path):
        with open(path, 'r') as file:
            return yaml.safe_load(file)

    def generate_email_content(self, recipient_name):
        template = self.template_env.get_template('email_template.html')
        context = {'name': recipient_name}
        return template.render(context)

# Example usage
generator = EmailContentGenerator('config.yaml')
print(generator.generate_email_content('John Doe'))
