import argparse
import os

def parse_arguments():
    parser = argparse.ArgumentParser(description='Process multiple files with options to specify output directories.')
    parser.add_argument('input_files', metavar='F', type=str, nargs='*',
                        help='Input file(s) to process')
    parser.add_argument('-o', '--output-dir', type=str, default='.',
                        help='Directory where processed files will be saved')
    parser.add_argument('-v', '--verbose', action='store_true',
                        help='Enable verbose mode for detailed output')
    return parser.parse_args()

def setup_output_directory(output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

def process_files(input_files, output_dir, verbose):
    if not input_files:
        print(""No files specified. Use -h for usage information."")
        return

    total_lines = 0
    for file in input_files:
        try:
            with open(file, 'r') as f:
                lines = f.readlines()
                total_lines += len(lines)

                if verbose:
                    print(f""Processing {file}..."")

                output_file_path = os.path.join(output_dir, os.path.basename(file))
                with open(output_file_path, 'w') as out_f:
                    for line in lines:
                        # Example processing: simply write the same line to output
                        out_f.write(line)

        except FileNotFoundError:
            print(f""Error: File {file} not found."")

    if verbose:
        print(f""Total number of lines processed: {total_lines}"")

def main():
    args = parse_arguments()
    setup_output_directory(args.output_dir)
    process_files(args.input_files, args.output_dir, args.verbose)

if __name__ == ""__main__"":
    main()
