import argparse
import os
import fnmatch
from collections import Counter

def count_text_files(directory, exclude_patterns=None):
    text_file_count = 0
    file_extension_counter = Counter()

    if exclude_patterns is None:
        exclude_patterns = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            if not any(fnmatch.fnmatch(file, pattern) for pattern in exclude_patterns):
                _, file_extension = os.path.splitext(file)
                if file_extension.lower() == '.txt':
                    text_file_count += 1
                    file_extension_counter[file_extension.lower()] += 1

    return text_file_count, file_extension_counter

def list_and_sort_extensions(counter):
    sorted_extensions = sorted(counter.items(), key=lambda x: x[1], reverse=True)
    return [f""{ext}: {count}"" for ext, count in sorted_extensions]

def find_largest_text_file(directory, exclude_patterns=None):
    largest_file_size = 0
    largest_file_path = ''

    if exclude_patterns is None:
        exclude_patterns = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            full_path = os.path.join(root, file)
            _, file_extension = os.path.splitext(file)

            if any(fnmatch.fnmatch(file, pattern) for pattern in exclude_patterns) or not file.endswith('.txt'):
                continue

            try:
                file_size = os.path.getsize(full_path)
                if file_size > largest_file_size:
                    largest_file_size = file_size
                    largest_file_path = full_path
            except OSError:
                pass  # Handle the case where a file cannot be accessed

    return largest_file_path, largest_file_size

def main():
    parser = argparse.ArgumentParser(description='Count all text files recursively within a directory and display detailed information.')
    parser.add_argument('--version', action='store_true', help='Display program version information')
    parser.add_argument('-d', '--directory', type=str, required=False, help='Specify a directory to traverse')
    parser.add_argument('-e', '--exclude-patterns', type=str, nargs='+', default=[], help='Patterns to exclude from counting')

    args = parser.parse_args()

    if args.version:
        print('Version 2.0')
        detailed_output = {
            'total_text_files': 0,
            'file_extensions': [],
            'largest_text_file': '',
            'largest_file_size': 0,
        }

        if not args.directory:
            print('Usage: python script.py -d /path/to/directory')
        else:
            try:
                total_text_files, file_extensions = count_text_files(args.directory, args.exclude_patterns)

                detailed_output['total_text_files'] = total_text_files
                detailed_output['file_extensions'] = list_and_sort_extensions(file_extensions)

                largest_file_path, largest_file_size = find_largest_text_file(args.directory, args.exclude_patterns)

                detailed_output['largest_text_file'] = largest_file_path
                detailed_output['largest_file_size'] = largest_file_size

                print(f""Total text files: {detailed_output['total_text_files']}"")
                for ext in detailed_output['file_extensions']:
                    print(ext)
                if detailed_output['largest_text_file']:
                    print(f""Largest text file: {detailed_output['largest_text_file']} ({detailed_output['largest_file_size']} bytes)"")
            except Exception as e:
                print(f""An error occurred: {e}"")

if __name__ == '__main__':
    main()
