import hashlib

class FileChecksumGenerator:
    def __init__(self):
        self.file_checksum_map = {}
        self.unique_checksums = set()

    def calculate_checksum(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                file_data = f.read()
            checksum = hashlib.sha256(file_data).hexdigest()
