package main

import (
	""errors""
	""fmt""
	""math/rand""
	""sync""
	""time""
)

type SessionIdentifierGenerator struct {
	mu         sync.Mutex
	existingIDs map[string]bool
}

func NewSessionIdentifierGenerator() *SessionIdentifierGenerator {
	return &SessionIdentifierGenerator{
		existingIDs: make(map[string]bool),
	}
}

func (g *SessionIdentifierGenerator) GenerateUniqueID(idRange int, quantity int) ([]string, error) {
	if idRange <= 0 || quantity <= 0 {
		return nil, errors.New(""invalid input parameters"")
	}

	g.mu.Lock()
	defer g.mu.Unlock()

	var ids []string
	for len(ids) < quantity {
		id := fmt.Sprintf(""%06d"", rand.Intn(idRange))
		if !g.existingIDs[id] {
			ids = append(ids, id)
			g.existingIDs[id] = true
		}
	}

	return ids, nil
}

type StudentRecord struct {
	name     string
	subjects map[string]float64
	weights  map[string]float64
}

func NewStudentRecord(name string) *StudentRecord {
	return &StudentRecord{
		name:     name,
		subjects: make(map[string]float64),
		weights:  make(map[string]float64),
	}
}

func (sr *StudentRecord) AddSubject(subject, grade float64) error {
	if subject == """" || grade < 0 {
		return errors.New(""invalid subject or grade"")
	}

	sr.subjects[fmt.Sprintf(""%f"", subject)] = grade
	return nil
}

func (sr *StudentRecord) SetWeight(subject, weight float64) error {
	if subject == """" || weight <= 0 {
		return errors.New(""invalid subject or weight"")
	}

	sr.weights[fmt.Sprintf(""%f"", subject)] = weight
	return nil
}

func (sr *StudentRecord) CalculateAverageGrade() (float64, error) {
	var totalWeight float64
	var weightedSum float64

	for subj, grade := range sr.subjects {
		subjectStr := fmt.Sprintf(""%f"", subj)
		weight, exists := sr.weights[subjectStr]
		if !exists {
			return 0, errors.New(""missing weight for subject"")
		}

		totalWeight += weight
		weightedSum += grade * weight
	}

	if totalWeight == 0 {
