import argparse
import os
import sys

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Unified program for file processing and command line argument parsing"")
    parser.add_argument(""input_files"", nargs=""+"", help=""Input files to process"")
    parser.add_argument(""-v"", ""--verbose"", action=""store_true"", help=""Enable verbose output"")
    parser.add_argument(""-o"", ""--output_directory"", default=""processed_files"", help=""Output directory for processed files"")
    return parser.parse_args()

def create_output_directory(output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

def process_file(input_file, output_directory, verbose=False):
    output_file = os.path.join(output_directory, os.path.basename(input_file))
    with open(input_file, ""r"") as f_in, open(output_file, ""w"") as f_out:
        lines_count = 0
        for line in f_in:
            lines_count += 1
            if verbose:
                print(f""Processing line: {line.strip()}"")
            f_out.write(line)
        print(f""Processed {lines_count} lines in file: {input_file}"")

def main():
    args = parse_arguments()
    create_output_directory(args.output_directory)

    if not args.input_files:
        print(""Usage: python script.py inputfile1 inputfile2 ... [-v] [-o output_directory]"")
        sys.exit(1)

    for input_file in args.input_files:
        process_file(input_file, args.output_directory, verbose=args.verbose)

if __name__ == ""__main__"":
    main()
