import json
import yaml
import pandas as pd
from openpyxl import load_workbook
import hashlib
from cryptography.fernet import Fernet

class DataProcessor:
    def __init__(self, config_path):
        self.config = self.load_config(config_path)
        self.security_key = self.generate_security_key()
        self.data_storage = []

    def load_config(self, config_path):
        with open(config_path, 'r') as file:
            return yaml.safe_load(file)

    def generate_security_key(self):
        return Fernet.generate_key()

    def load_data(self, file_path):
        supported_formats = ['json', 'csv', 'xlsx']
        format = file_path.split('.')[-1]

        if format not in supported_formats:
            raise ValueError(f""Unsupported file format: {format}"")

        if format == 'json':
            return json.load(open(file_path))
        elif format == 'csv':
            return pd.read_csv(file_path)
        elif format == 'xlsx':
            return pd.read_excel(load_workbook(file_path))

    def save_data(self, data, file_type):
        if file_type == 'json':
            with open('output.json', 'w') as f:
                json.dump(data, f)
            print(""Data saved as JSON."")
        elif file_type == 'csv':
            data.to_csv('output.csv', index=False)
            print(""Data saved as CSV."")
        elif file_type == 'xlsx':
            writer = pd.ExcelWriter('output.xlsx')
            data.to_excel(writer)
            writer.save()
            print(""Data saved as XLSX."")

    def process_data(self, data):
        # Example processing: hash the data for integrity check
        if isinstance(data, dict):  # JSON data
            json_str = json.dumps(data, sort_keys=True)
            data_hash = hashlib.sha256(json_str.encode()).hexdigest()
            return {'processed_data': data, 'hash': data_hash}

        elif isinstance(data, pd.DataFrame):  # CSV/XLSX data
            for col in data.select_dtypes(include=['object']):
                data[col] = data[col].apply(lambda x: hashlib.sha256(x.encode()).hexdigest() if pd.notnull(x) else x)
            return data

# Unit tests using pytest and performance testing with cProfile can be created as follows:

def test_load_data_json():
    processor = DataProcessor('config.yaml')
    data = processor.load_data('test.json')
    assert isinstance(data, dict)

def test_load_data_csv():
    processor = DataProcessor('config.yaml')
    data = processor.load_data('test.csv')
    assert isinstance(data, pd.DataFrame)

def test_load_data_xlsx():
    processor = DataProcessor('config.yaml')
    data = processor.load_data('test.xlsx')
    assert isinstance(data, pd.DataFrame)

def test_process_data_json():
    processor = DataProcessor('config.yaml')
    json_data = {'key': 'value'}
    processed = processor.process_data(json_data)
    assert 'hash' in processed

def test_process_data_csv():
    processor = DataProcessor('config.yaml')
    csv_data = pd.DataFrame({'col1': ['data1', 'data2']})
    processed = processor.process_data(csv_data)
    assert not processed['col1'].isnull().any()  # Ensure no nulls in hashed column

# Performance testing
def profile_process_data():
    processor = DataProcessor('config.yaml')
    large_csv_data = pd.DataFrame({'col1': ['data'] * 1000000})
    cProfile.runctx(""processor.process_data(large_csv_data)"", globals(), locals())

# To run the tests, use pytest in the command line: `pytest <filename>.py`
