import sys
import numpy as np

def read_temperature_data(file_path):
    try:
        with open(file_path, 'r') as file:
            return [float(line.strip()) for line in file]
    except FileNotFoundError:
        print(""Error: File not found."")
        sys.exit(1)
    except ValueError:
        print(""Error: Invalid data format."")
        sys.exit(1)

def write_results(results, output_file):
    try:
        with open(output_file, 'w') as file:
            for result in results:
                file.write(f""{result}\n"")
    except IOError:
        print(""Error: Unable to write to output file."")
        sys.exit(1)

def calculate_average_temperature(temperatures, month_days):
    average_temperatures = []

    for day in range(1, month_days + 1):
        daily_temperatures = [temp for idx, temp in enumerate(temperatures) if idx % 24 == day - 1]

        if len(daily_temperatures) == 0:
            average_temperatures.append(None)
            continue

        filtered_temperatures = remove_outliers(daily_temperatures)

        if len(filtered_temperatures) == 0:
            average_temperatures.append(None)
            continue

        average_temperature = np.mean(filtered_temperatures)

        average_temperatures.append(average_temperature)

    return average_temperatures

def remove_outliers(daily_temperatures):
    quartiles = np.percentile(daily_temperatures, [25, 75])

    iqr = quartiles[1] - quartiles[0]

    lower_bound = quartiles[0] - (iqr * 3)
    upper_bound = quartiles[1] + (iqr * 3)

    return [temp for temp in daily_temperatures if lower_bound < temp < upper_bound]

if __name__ == ""__main__"":
    import os

    if len(sys.argv) < 2 or len(sys.argv) > 4:
        print(""Usage: python script.py input_file [output_file] [criteria]"")
        sys.exit(0)

    input_file_path = sys.argv[1]

    output_file_path = None
    criteria_thresholds = {'min': None, 'max': None}

    if len(sys.argv) > 2 and os.path.exists(sys.argv[2]):
        output_file_path = sys.argv[2]

    if len(sys.argv) > 3:
        try:
            min_temp, max_temp = map(float, sys.argv[3].split(','))
            criteria_thresholds['min'] = min_temp
            criteria_thresholds['max'] = max_temp
        except ValueError:
            print(""Error: Invalid criteria format."")
            sys.exit(1)

    temperatures = read_temperature_data(input_file_path)

    if criteria_thresholds['min'] is not None and criteria_thresholds['max'] is not None:
        temperatures = [temp for temp in temperatures if criteria_thresholds['min'] <= temp <= criteria_thresholds['max']]

    month_days = (len(temperatures) + 23) // 24

    average_temperatures = calculate_average_temperature(temperatures, month_days)

    if output_file_path:
        write_results(average_temperatures, output_file_path)
    else:
        for temp in average_temperatures:
            print(temp)
