import hmac
import hashlib
import time
import uuid

class SecureDynamicLink:
    def __init__(self, link_id, timestamp=None, hmac_secret=None):
        self.link_id = link_id
        self.timestamp = timestamp or int(time.time())
        self.hmac_secret = hmac_secret or uuid.uuid4().hex  # Generate a new secret if not provided

    @staticmethod
    def generate_hmac(data, key):
        return hmac.new(key.encode(), data.encode(), hashlib.sha256).hexdigest()

    def validate_link(self, link_data):
        current_time = int(time.time())
        time_difference = abs(current_time - self.timestamp)

        # Check timestamp within 5-minute tolerance (300 seconds)
        if time_difference > 300:
            return False

        # Compare HMACs
        expected_hmac = SecureDynamicLink.generate_hmac(link_data, self.hmac_secret)
        actual_hmac = link_data.get('hmac')

        return hmac.compare_digest(expected_hmac, actual_hmac)

def generate_secure_dynamic_links(count, existing_ids):
    secure_links = []
    while len(secure_links) < count:
        link_id = uuid.uuid4().hex
        if link_id not in existing_ids:
            link = SecureDynamicLink(link_id)
            secure_links.append(link)
            existing_ids.add(link_id)

    return secure_links

