import random
import uuid
import logging

# Set up basic configuration for logging
logging.basicConfig(filename='ndcr_generation.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

class NetworkDeviceConfigRequest:
    def __init__(self, node_id, ip_address, port_number, mac_address=None):
        self.node_id = node_id
        self.ip_address = ip_address
        self.port_number = port_number
        self.mac_address = mac_address or self.generate_mac_address()

    @staticmethod
    def generate_mac_address(node_id):
        random_hex = uuid.uuid4().hex[:6]
        return f""{node_id:012X}-{random_hex}""

    def __str__(self):
        return (f""Node ID: {self.node_id}, IP Address: {self.ip_address}, ""
                f""Port Number: {self.port_number}, MAC Address: {self.mac_address}"")

def generate_ip_address():
    # Generate a random valid IPv4 address
    return ""."".join(map(str, (random.randint(1, 255) for _ in range(4))))

def create_ndcr_array(size, ip_version=4):
    if size <= 0:
        raise ValueError(""Array size must be greater than zero."")

    ndcr_list = []
    try:
        for i in range(size):
            node_id = i + 1
            ip_address = generate_ip_address()
            port_number = random.randint(1024, 65535)

            ndcr = NetworkDeviceConfigRequest(node_id, ip_address, port_number)
            ndcr_list.append(ndcr)

            logging.info(f""Generated NDCR: {ndcr}"")

    except Exception as e:
        logging.error(""An error occurred while generating NDCR structures."", exc_info=True)
        raise

    return ndcr_list

def save_ndcr_to_file(ndcr_array, file_path):
    try:
        with open(file_path, 'w') as f:
            for ndcr in ndcr_array:
                f.write(str(ndcr) + ""\n"")

        logging.info(f""NDCR structures saved to {file_path}"")

    except Exception as e:
        logging.error(""Failed to save NDCR structures to file."", exc_info=True)
        raise

# Example usage
try:
    ndcr_structures = create_ndcr_array(5)  # Create an array of 5 NDCRs
    for ndcr in ndcr_structures:
        print(ndcr)

    save_ndcr_to_file(ndcr_structures, 'ndcr_output.txt')

except ValueError as ve:
    logging.error(f""ValueError: {ve}"")
except Exception as e:
    logging.error(f""Unhandled exception occurred: {e}"")

