def optimize_image_files(image_paths: List[str]):
    for path in image_paths:
        try:
            if os.path.exists(path):
                result = subprocess.run(
                    ['./image_optimizer', path],
                    capture_output=True,
                    text=True
                )
                if result.returncode != 0:
                    print(f""Failed to optimize {path}: {result.stderr}"")
                else:
                    print(f""Successfully optimized {path}"")
            else:
                print(f""File not found: {path}"")
        except Exception as e:
            print(f""Error optimizing image {path}: {str(e)}"")


def main():
