The combined approach ensures that users can efficiently manage digital libraries with secure encryption mechanisms and efficient data handling processes through advanced features such as custom AES operations and image parsing capabilities tailored for enhanced security and usability in a digital catalog environment.",['CWE-121'],,"['Below is an implementation of the described library management system using OpenSSL's cryptographic functionalities. This code provides functions to handle DES-based ciphers, encryption/decryption of book records, file export/import, and sorting within search result sets.

```python
import os
from Crypto.Cipher import DES3
from Crypto.Util.Padding import pad, unpad

class LibraryManagementSystem:
    def __init__(self):
        self.records = {}

    @staticmethod
    def get_des_cipher(mode, key):
        if mode == ""ECB"":
            return DES3.new(key, DES3.MODE_ECB)
        elif mode == ""EDE"":
            return DES3.new(key, DES3.MODE_CBC, iv=b'0000000000000000')
        elif mode == ""EDE3"":
            return DES3.new(key, DES3.MODE_CFB, iv=b'0000000000000000')
        elif mode == ""CFB"":
            return DES3.new(key, DES3.MODE_CFB, iv=b'0000000000000000')
        else:
            # Null encryption for testing purposes
            class NullCipher:
                def encrypt(self, data):
                    return data

                def decrypt(self, data):
                    return data

            return NullCipher()

    def add_or_update_record(self, record_id, title, author, genre, year, key, mode=""ECB""):
        cipher = self.get_des_cipher(mode, key)
        encrypted_data = cipher.encrypt(pad(f""{title},{author},{genre},{year}"".encode(), DES3.block_size))
        self.records[record_id] = (encrypted_data, mode)

    def search_records(self, metadata):
        results = []
        for record_id, (data, mode) in self.records.items():
            cipher = self.get_des_cipher(mode, key)
            decrypted_data = unpad(cipher.decrypt(data), DES3.block_size).decode()
            title, author, genre, year = decrypted_data.split(',')
            if all(meta in decrypted_data for meta in metadata):
                results.append((record_id, decrypted_data))
        return sorted(results, key=lambda x: (x[1].split(',')[3], x[1].split(',')[2]))  # Sort by year then genre

    def export_records(self, filename, key, mode=""ECB""):
        with open(filename, 'wb') as file:
            for record_id, (data, rec_mode) in self.records.items():
                if rec_mode != mode:  # Re-encrypt if necessary
                    cipher = self.get_des_cipher(rec_mode, key)
                    decrypted_data = unpad(cipher.decrypt(data), DES3.block_size).decode()
                    new_cipher = self.get_des_cipher(mode, key)
                    data = new_cipher.encrypt(pad(decrypted_data.encode(), DES3.block_size))
                file.write(f""{record_id}:{data.decode()}|"".encode())
            file.write(b'END')

    def import_records(self, filename, key, mode=""ECB""):
        with open(filename, 'rb') as file:
            content = file.read().decode()
            for record in content.split('|'):
                if record == ""END"":
                    break
                record_id, data = record.split(':')
                cipher = self.get_des_cipher(mode, key)
                decrypted_data = unpad(cipher.decrypt(data.encode()), DES3.block_size).decode()
                title, author, genre, year = decrypted_data.split(',')
                self.add_or_update_record(record_id, title, author, genre, year, key, mode)

# Usage example
library_system = LibraryManagementSystem()

# Example encryption key (must be 24 bytes for Triple DES)
encryption_key = b'123456789012345678901234'

# Add a new record
library_system.add_or_update_record(""001"", ""The Great Gatsby"", ""F. Scott Fitzgerald"", ""Novel"", ""1925"", encryption_key, mode=""ECB"")

# Search and sort records (assuming metadata search criteria)
search_results = library_system.search_records([""Novel""])
print(search_results)

# Export to a file
library_system.export_records(""library_backup.dat"", encryption_key, mode=""ECB"")

# Import from a file
library_system.import_records(""library_backup.dat"", encryption_key, mode=""ECB"")
```

### Explanation:
- **Cipher Initialization**: The `get_des_cipher` method initializes the DES cipher in different modes: ECB, EDE (CBC), EDE3 (CFB), and CFB. Null encryption is used for testing.
- **Record Management**: Records are stored with encrypted data. Adding or updating records involves encrypting metadata fields concatenated into a single string.
- **Search Functionality**: Searches through decrypted record data to match specified metadata, sorting by year and genre.
- **Export/Import**: Handles re-encryption during export if necessary and decrypts records during import.

This code provides a secure way to manage library records with encryption using DES3 from the `pycryptodome` library. Adjustments may be needed based on specific system requirements or additional functionality.']",274,[0],[],True,0,0,0,

