import sys

def count_lines(filename):
    with open(filename, 'r') as file:
        return sum(1 for _ in file)

def main():
    if len(sys.argv) < 2:
        print(""Error: At least one input argument is required."")
        sys.exit(1)

    manpage_flag = False
    cs_flag = False
    output_file = None

    args = iter(sys.argv[1:])

    for arg in args:
        if arg == '--manpage':
            manpage_flag = True
        elif arg == '-cs':
            cs_flag = True
        elif arg == '-o':
            try:
                output_file = next(args)
            except StopIteration:
                print(""Error: '-o' flag requires an argument."")
                sys.exit(1)
        else:
            input_file = arg

    if not (manpage_flag or cs_flag or output_file):
        input_file = args[0]

    if output_file:
        try:
            line_count = count_lines(output_file)
            print(f""Number of lines in {output_file}: {line_count}"")
        except FileNotFoundError:
            print(f""Error: File '{output_file}' not found."")
        except Exception as e:
            print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()
