def process_email_content(content, delimiter_start, delimiter_end):
    result_c_str = lib.append_delimiters(ffi.new(""char[]"", content.encode('utf-8')),
                                         ffi.new(""char[]"", delimiter_start.encode('utf-8')),
                                         ffi.new(""char[]"", delimiter_end.encode('utf-8')))
    return ffi.string(result_c_str).decode()

def send_email(email, subject, body):
    msg = MIMEText(body)
    msg['Subject'] = subject
    msg['From'] = 'sender@example.com'
    msg['To'] = email

    try:
        with smtplib.SMTP('smtp.example.com') as server:  # Update SMTP details
            server.sendmail(msg['From'], [msg['To']], msg.as_string())
        logging.info(f'Email sent to {email}')
    except Exception as e:
        logging.error(f'Failed to send email to {email}: {e}')

def schedule_emails(config):
    scheduler = BlockingScheduler()

    for entry in config['emails']:
        template_loader = jinja2.FileSystemLoader(searchpath=""./templates"")
        template_env = jinja2.Environment(loader=template_loader)
        template = template_env.get_template(entry['template'])

        subject = entry.get('subject', 'No Subject')
        content_with_delimiters = process_email_content(
            entry['content'],
            entry['delimiter_start'],
            entry['delimiter_end']
        )
        body = template.render(content=content_with_delimiters)

        scheduler.add_job(send_email, 'date',
                          run_date=entry['send_time'],
                          args=[entry['recipient'], subject, body])

    try:
        scheduler.start()
    except (KeyboardInterrupt, SystemExit):
        logging.info('Scheduler shut down.')

if __name__ == '__main__':
    config = load_yaml_config('config.yaml')
    schedule_emails(config)
