import uuid
import json
import logging
from typing import List

# Configure logging
logging.basicConfig(filename='sacr_log.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def generate_sacr_array(size: int, raid_types: List[str], capacities_gb: List[int]) -> List[dict]:
    if not isinstance(size, int) or size <= 0:
        raise ValueError(""Size must be a positive integer."")

    if not all(isinstance(raid_type, str) for raid_type in raid_types):
        raise ValueError(""RAID types should be provided as strings."")

    if not all(isinstance(capacity, int) and capacity > 0 for capacity in capacities_gb):
        raise ValueError(""Capacities must be positive integers."")

    def create_sacr(raid_type: str, capacity: int) -> dict:
        storage_array_id = f""array_{uuid.uuid4().hex}""
        return {
            ""Storage Array ID"": storage_array_id,
            ""RAID Type"": raid_type,
            ""Capacity (GB)"": capacity,
            ""Metadata"": {
                ""UUID"": uuid.uuid5(uuid.NAMESPACE_DNS, storage_array_id)
            }
        }

    sacr_list = []

    for _ in range(size):
        for raid_type in raid_types:
            for capacity in capacities_gb:
                try:
                    sacr = create_sacr(raid_type, capacity)
                    logging.info(f""Created SACR: {sacr}"")
                    sacr_list.append(sacr)

                except Exception as e:
                    logging.error(f""Failed to create SACR: {e}"")

    return sacr_list

def save_to_file(data: List[dict], filename: str = ""sacr_output.json"") -> None:
    try:
        with open(filename, 'w') as file:
            json.dump(data, file, indent=4)
        logging.info(f""Data successfully saved to {filename}"")
    except IOError as e:
        logging.error(f""Failed to save data to file: {e}"")

def main():
    size = 10
    raid_types = [""RAID0"", ""RAID1"", ""RAID5""]
    capacities_gb = [100, 200, 500]

    try:
        sacr_array = generate_sacr_array(size, raid_types, capacities_gb)
        print(json.dumps(sacr_array, indent=4))
        save_to_file(sacr_array)

    except ValueError as e:
        logging.error(f""Input validation error: {e}"")

if __name__ == ""__main__"":
    main()
```

