class GenericCompressor:
    def __init__(self):
        self.dictionary = {}

    def compress(self, data):
        output = []
        current_string = """"
        for symbol in data:
            combined_string = current_string + symbol
            if combined_string in self.dictionary:
                current_string = combined_string
            else:
                if current_string:
                    output.append(self.dictionary[current_string])
                index = len(self.dictionary)
                self.dictionary[combined_string] = index
                current_string = symbol

        if current_string:
            output.append(self.dictionary[current_string])

        return output

    def decompress(self, compressed_data):
        reverse_dictionary = {v: k for k, v in self.dictionary.items()}
        current_index = compressed_data.pop(0)
        current_string = reverse_dictionary[current_index]
        output = [current_string]

        for index in compressed_data:
            if index in reverse_dictionary:
                entry = reverse_dictionary[index]
            elif index == len(self.dictionary):
                entry = current_string + current_string[0]
            else:
                raise ValueError(""Invalid compressed data"")

            output.append(entry)
            self.dictionary[len(self.dictionary)] = current_string + entry[0]
            current_string = entry

        return """".join(output)


# Test cases
def test_generic_compressor():
    compressor = GenericCompressor()
    original_data = ""TOBEORNOTTOBEORTOBEORNOT""
    compressed_data = compressor.compress(original_data)

    assert compressor.decompress(compressed_data) == original_data, ""Decompression failed to match the original data""

test_generic_compressor()

