import random
import time

def get_sequence_number_from_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            if not lines:
                raise IndexError(""File is empty"")
            last_line = lines[-1]
            # Assuming the sequence number is an integer at the end of the line
            sequence_number = int(last_line.strip().split()[-1])
        return sequence_number
    except FileNotFoundError:
        print(f""Error: The file {file_path} was not found."")
        return None
    except (IndexError, ValueError) as e:
        print(f""Error processing the file: {e}"")
        return None

def generate_nfa_commands(num_commands):
    commands = []
    for _ in range(num_commands):
        command_pdu = {
            ""TGI"": random.randint(1, 1000),  # Random TGI between 1 and 1000
            ""scheduled"": bool(random.getrandbits(1)),  # Random boolean value
            ""timestamp"": time.time()  # Current timestamp
        }
        commands.append(command_pdu)
    return commands

def main():
    file_path = input(""Enter the path to the sequence number file: "")
    sequence_number = get_sequence_number_from_file(file_path)

    if sequence_number is not None:
        print(f""Sequence Number: {sequence_number}"")

    try:
        num_commands = int(input(""How many commands would you like to generate? ""))
    except ValueError:
        print(""Invalid input. Please enter an integer."")
        return

    nfa_commands = generate_nfa_commands(num_commands)
    for command in nfa_commands:
        print(command)

if __name__ == ""__main__"":
    main()
