import re

def parseLogEntries(log_file_path):
    log_entries = []

    try:
        with open(log_file_path, 'r') as file:
            for line in file:
                # Skip comments and empty lines
                if line.startswith('#') or not line.strip():
                    continue

                # Define pattern for a valid log entry (example: date-time severity message)
                pattern = r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ([A-Z]+) (.+)'
                match = re.match(pattern, line.strip())

                if match:
                    try:
                        # Extract components of the log entry
                        timestamp, severity, message = match.groups()

                        # Create a structured dictionary for each valid log entry
                        log_entry = {
                            'timestamp': timestamp,
                            'severity': severity,
                            'message': message
                        }
                        log_entries.append(log_entry)

                    except Exception as e:
                        print(f""Error processing line: {line}. Error: {e}"")
                        return -1  # Indicate error in parsing

        return log_entries

    except FileNotFoundError:
        print(""Log file not found."")
        return -2  # File not found error code

    except IOError as e:
        print(f""I/O error occurred: {e}"")
        return -3  # I/O related error code
```

This function `parseLogEntries` reads a log file line by line, skips comments and empty lines, checks for valid entries using regular expressions to extract timestamp, severity, and message, then organizes them into structured dictionary objects. Error handling is included to manage issues like file not found or I/O errors.']",415,[0],[],True,0,0,0,

