import json
import random
import string
import jwt  # PyJWT library

def generate_jwt_object(header_key, header_value, username, role, secret):
    header = {
        ""alg"": random.choice([""HS256"", ""RS256""]),
        payload_key: random.randint(1, 1000)
    }

    payload = {
        ""sub"": username,
        ""role"": role
    }

    encoded_jwt = jwt.encode(payload=payload, key=secret, algorithm=header[""alg""])
    signature = encoded_jwt.split(""."")[-1]

    return {
        ""header"": header,
        ""payload"": payload,
        ""signature"": signature
    }

def generate_jwt_array(num_tokens, secret_key):
    if not isinstance(num_tokens, int) or num_tokens <= 0:
        raise ValueError(""Number of tokens must be a positive integer."")

    jwt_objects = []

    for _ in range(num_tokens):
        header_key = ''.join(random.choices(string.ascii_letters, k=5))
        header_value = ''.join(random.choices(string.digits, k=5))

        username = ''.join(random.choices(string.ascii_lowercase, k=8))
        role = random.choice([""admin"", ""user"", ""guest""])

        jwt_obj = generate_jwt_object(header_key, header_value, username, role, secret_key)
        jwt_objects.append(jwt_obj)

    return jwt_objects

