1,"Design a library management program. It should enable users to add, remove, and update book records. Each record must include title, author, publication year, and genre. Implement search functionality for books by title, author, or genre. Add sorting by publication year or genre. Include options for exporting the collection to a file and importing from a file.",['CWE-121'],,"['```python
import json

class LibraryManagement:
    def __init__(self):
        self.books = []

    def add_book(self, title, author, publication_year, genre):
        self.books.append({
            ""title"": title,
            ""author"": author,
            ""publication_year"": publication_year,
            ""genre"": genre
        })

    def remove_book(self, title):
        self.books = [book for book in self.books if book['title'] != title]

    def update_book(self, old_title, new_title=None, new_author=None, new_publication_year=None, new_genre=None):
        for book in self.books:
            if book['title'] == old_title:
                if new_title: book['title'] = new_title
                if new_author: book['author'] = new_author
                if new_publication_year: book['publication_year'] = new_publication_year
                if new_genre: book['genre'] = new_genre

    def search_books(self, search_type, keyword):
        return [book for book in self.books if book[search_type] == keyword]

    def sort_books_by_year(self):
        return sorted(self.books, key=lambda x: x['publication_year'])

    def sort_books_by_genre(self):
        return sorted(self.books, key=lambda x: x['genre'])

    def export_to_file(self, filename):
        with open(filename, 'w') as file:
            json.dump(self.books, file)

    def import_from_file(self, filename):
        with open(filename, 'r') as file:
            self.books = json.load(file)

# Example usage
library = LibraryManagement()
library.add_book(""1984"", ""George Orwell"", 1949, ""Dystopian"")
library.export_to_file(""books.json"")
library.import_from_file(""books.json"")
