import time
import os
import hashlib
import logging
from typing import List

class InvalidLinkIdException(Exception):
    pass

class DynamicLink:
    def __init__(self, link_id: int, timestamp: float, secret_key: bytes):
        self.link_id = link_id
        self.timestamp = timestamp
        self.secret_key = secret_key

def create_dynamic_links(max_links: int = 100, secret_key_length: int = 32) -> List[DynamicLink]:
    links_created = set()
    generated_links = []
    try:
        for _ in range(max_links):
            link_id = generate_unique_link_id(links_created)
            timestamp = time.time()
            secret_key = generate_secure_secret_key(secret_key_length)
            new_link = DynamicLink(link_id, timestamp, secret_key)
            links_created.add(link_id)
            generated_links.append(new_link)

        log_creation_info(generated_links)

    except Exception as e:
        logging.error(f""Failed to generate links due to {str(e)}"")

    return generated_links

def generate_unique_link_id(links_created: set) -> int:
    while True:
        link_id = os.urandom(8).hex()[:8]
        if link_id not in links_created:
            return int(link_id)

def generate_secure_secret_key(key_length: int) -> bytes:
    try:
        return os.urandom(key_length)
    except Exception as e:
        logging.error(f""Failed to generate secure key due to {str(e)}"")
        raise

def log_creation_info(links: List[DynamicLink]):
    logging.basicConfig(level=logging.INFO)
    for link in links:
        logging.info(f""Generated Link ID: {link.link_id}, Timestamp: {link.timestamp}, Secret Key Length: {len(link.secret_key)} bytes"")

def validate_dynamic_link(link_to_validate: DynamicLink) -> bool:
    try:
        expected_hash = hashlib.sha256((str(link_to_validate.link_id) + str(link_to_validate.timestamp)).encode()).hexdigest()
        actual_hash_with_salt = hashlib.sha256((str(link_to_validate.link_id) + str(link_to_validate.timestamp) + str(hashlib.sha256(link_to_validate.secret_key).hexdigest())).encode()).hexdigest()

        if expected_hash == actual_hash_with_salt[:len(expected_hash)] and len(expected_hash) == len(actual_hash_with_salt):
            return True

        return False

    except Exception as e:
        logging.error(f""Validation failed due to {str(e)}"")
