import hashlib
import time

class EmailVerificationCode:
    def __init__(self, email, verification_code, expiration_time=None):
        self.email = email
        self.expiration_time = expiration_time or time.time() + 3600  # Default to 1 hour from now
        self.verification_code = verification_code

    def validate_code(self, provided_code):
        if time.time() > self.expiration_time:
            return False

        generated_code = self._generate_verification_code()
        return hashlib.sha256(provided_code.encode()).hexdigest() == hashlib.sha256(generated_code.encode()).hexdigest()

    def _generate_verification_code(self):
        hash_object = hashlib.sha256((self.email + str(self.verification_code)).encode())
        return hash_object.hexdigest()


def generate_email_verification_codes(emails, num_codes):
    codes_dict = {}

    for email in emails:
        used_combinations = set()

        for i in range(num_codes):
            unique_identifier = f""{email}{i}""

            while hashlib.sha256(unique_identifier.encode()).hexdigest() in used_combinations:
                i += 1
                unique_identifier = f""{email}{i}""

            code = hashlib.sha256(unique_identifier.encode()).hexdigest()
            if email not in codes_dict:
                codes_dict[email] = []
            codes_dict[email].append((unique_identifier, code))

            used_combinations.add(code)

    return codes_dict

