import csv

def process_csv(input_file, output_file, condition_for_extraction):
    def safe_eval_condition(condition_str, row):
        try:
            return eval(condition_str)(row)
        except Exception as e:
            print(f""Error evaluating condition: {e}"")
            return False

    with open(input_file) as file:
        reader = csv.DictReader(file)
        with open(output_file, 'w') as out:
            writer = csv.DictWriter(out, fieldnames=reader.fieldnames)
            writer.writeheader()
            for row in reader:
                if safe_eval_condition(condition_for_extraction, row):
                    writer.writerow(row)

def manage_database_transactions(db_config_files):
    db_connections = {}

    for db_config_path in db_config_files:
        db_name = os.path.splitext(os.path.basename(db_config_path))[0]

        with open(db_config_path) as file:
            db_config_data = json.load(file)

        db_url = db_config_data['db_url']

        conn, cursor = connect_to_db(db_url)
        db_connections[db_name] = (conn, cursor)

    # Sample usage of transactions and rollback
    try:
        for db_name, (conn, cursor) in db_connections.items():
            sql_statements = db_config_data.get('sql_statements', [])
            execute_queries(conn, cursor, sql_statements)

    except Exception as e:
        print(f""Transaction failed: {e}"")
        for conn, _ in db_connections.values():
            conn.rollback()

    finally:
        for _, (conn, _) in db_connections.items():
            conn.close()
