import hmac
import hashlib
import time
import random
import socket

class SecureDynamicLink:
    def __init__(self, link_id, timestamp, secret):
        self.link_id = link_id
        self.timestamp = timestamp
        self.secret = secret

    @staticmethod
    def generate_hmac(secret, data):
        return hmac.new(secret.encode(), data.encode(), hashlib.sha256).hexdigest()

    def validate_link(self, provided_hmac, timeout=300):
        current_time = int(time.time())
        if abs(current_time - self.timestamp) > timeout:
            return False

        expected_hmac = SecureDynamicLink.generate_hmac(self.secret, f""{self.link_id}:{self.timestamp}"")
        return hmac.compare_digest(provided_hmac, expected_hmac)

def generate_secure_dynamic_links(existing_link_ids, secret):
    while True:
        link_id = str(random.randint(1000, 9999))
        if link_id not in existing_link_ids:
            timestamp = int(time.time())
            new_link = SecureDynamicLink(link_id, timestamp, secret)
            existing_link_ids.add(link_id)
            return new_link

class DNSConfig:
    def __init__(self):
        self.servers = []

    def create_dns_servers(self, num_servers, ip_range, port_range, weight_range):
        for _ in range(num_servers):
            # Generate a random IP address
            ip_parts = [str(random.randint(ip_range[0], ip_range[1])) for _ in range(4)]
            ip_address = ""."".join(ip_parts)

            # Ensure the IP is valid
            try:
                socket.inet_aton(ip_address)
            except socket.error:
                continue

            port = random.randint(port_range[0], port_range[1])
            weight = round(random.uniform(weight_range[0], weight_range[1]), 2)

            server_config = {
                'ip': ip_address,
                'port': port,
                'weight': weight
            }
            self.servers.append(server_config)

# Example usage:
if __name__ == ""__main__"":
    # Generating a new secure dynamic link
    existing_links = set()
    secret_key = ""super_secret""
    new_link = generate_secure_dynamic_links(existing_links, secret_key)
    print(f""New Link: {new_link.link_id}, Timestamp: {new_link.timestamp}"")

    # Creating DNS server configurations
    dns_config = DNSConfig()
    num_servers_to_create = 5
    ip_range = (1, 254)  # Valid IP range for each octet (excluding network and broadcast addresses)
    port_range = (1024, 65535)  # Usable port range
    weight_range = (0.1, 10.0)  # Example weight range

    dns_config.create_dns_servers(num_servers_to_create, ip_range, port_range, weight_range)
    for server in dns_config.servers:
        print(f""DNS Server: IP={server['ip']}, Port={server['port']}, Weight={server['weight']}"")
