import os
import numpy as np
from mutagen import File
from mido import MidiFile

def is_valid_midi_file(file_path):
    try:
        midi = MidiFile(file_path)
        return True
    except Exception:
        return False

def extract_midi_info(file_path):
    if not is_valid_midi_file(file_path):
        return ""Error: Invalid MIDI file format.""

    midi_data = MidiFile(file_path)
    tracks_info = []

    for i, track in enumerate(midi_data.tracks):
        tempo = None
        time_signature = None
        key_signature = None

        first_measure_notes = []
        for msg in track:
            if msg.type == 'set_tempo':
                tempo = msg.tempo / 60000000
            elif msg.type == 'time_signature':
                numerator, denominator = divmod(msg.denominator, 2**msg.numerator)
                time_signature = (numerator * 2**12) / denominator
            elif msg.type == 'key_signature':
                key_signature = int(msg.key)

            if msg.time < 3:
                first_measure_notes.append(msg.note)

        print(f""Track {i+1} Information: Tempo={tempo}, Time Signature={time_signature}, Key Signature={key_signature}, Notes={first_measure_notes}"")

def resolveDNS(hostname):
    pid = os.fork()

    if pid == -1:
        print(""Failed to create child process"")
        return -1

    if pid == 0:
        cmd_line =""dig +short "" + hostname
        os.system(cmd_line)
        with open(""/var/run/named/dns.pid"", ""r"") as fdout:
            ipBuffer = """"
            while True:
                line = fdout.readline()
                if not line:
                    break
                ipBuffer += line

        print(f""Resolved IP: {ipBuffer.strip()}"")
    else:
        os.waitpid(pid, 0)

if __name__ == ""__main__"":
    midi_file_path = ""path/to/midi/file.mid""
    hostname = ""example.com""

    extract_midi_info(midi_file_path)
    resolveDNS(hostname)
